1	//! Typed facade over jj: reads and the publish-path mutations, all
2	//! in-process through jj-lib (the jj-lib migration stage of
3	//! `notes/refactor-20260716.md`).
4	//!
5	//! Reads resolve through `common::load_repo` +
6	//! `common::resolve_revset` and `Commit` accessors; a revset that
7	//! references a working copy (`@`, `@-`, `ws@`) snapshots first
8	//! (`repo_for_read`), so "right now" questions answer about the
9	//! filesystem the way the spawned CLI's auto-snapshot did.
10	//! Mutations run on the `session` module's `RepoSession`: its
11	//! settings / snapshot / transaction-finish plumbing.
12	//!
13	//! - `matches` / `rev_exists`: does a revset match / does a
14	//!   revision resolve.
15	//! - `chid_of` / `cid_of` / `cid_short_of` / `cids_short_of`:
16	//!   change / commit ids.
17	//! - `desc_of` / `is_empty`: description and emptiness.
18	//! - `is_no_such_revision`: the typed unresolvable-revision test.
19	//! - `commit` / `describe` / `bookmark_set` / `git_push_bookmark` /
20	//!   `git_fetch`: the publish-path mutations.
21	//!
22	//! Still spawning `jj` elsewhere: `bookmark_list` /
23	//! `bookmark_list_all` here (their consumers parse the CLI listing
24	//! textually), and the call sites outside the five verbs
25	//! (`jj squash`, `jj new`, `jj rebase`, `jj op log` / `op restore`,
26	//! `jj git clone`, `jj diff --stat`, repo-init plumbing).
27	
28	use std::path::Path;
29	
30	use jj_lib::commit::Commit;
31	use jj_lib::object_id::ObjectId;
32	use jj_lib::repo::Repo;
33	use jj_lib::revset::RevsetResolutionError;
34	use pollster::FutureExt;
35	
36	use crate::common;
37	
38	mod session;
39	
40	/// Crate-standard boxed-error result, aliased locally for brevity.
41	type Result<T> = std::result::Result<T, Box<dyn std::error::Error>>;
42	
43	/// `desc` with the trailing newline jj normalizes descriptions to.
44	fn complete_newline(desc: &str) -> String {
45	    if desc.is_empty() || desc.ends_with('\n') {
46	        desc.to_string()
47	    } else {
48	        format!("{desc}\n")
49	    }
50	}
51	
52	/// Snapshot the working copy, then update the wc commit's
53	/// description and start a new empty change on top (`jj commit`).
54	pub fn commit(repo: &Path, desc: &str) -> Result<()> {
55	    let mut ses = session::RepoSession::open(repo)?;
56	    ses.snapshot()?;
57	    let wc_commit = ses.wc_commit()?;
58	    let name = ses.workspace.workspace_name().to_owned();
59	    let mut tx = ses.start_tx();
60	    let new_commit = tx
61	        .repo_mut()
62	        .rewrite_commit(&wc_commit)
63	        .set_description(complete_newline(desc))
64	        .write()
65	        .block_on()?;
66	    let new_wc_commit = tx
67	        .repo_mut()
68	        .new_commit(vec![new_commit.id().clone()], wc_commit.tree())
69	        .write()
70	        .block_on()?;
71	    tx.repo_mut().edit(name, &new_wc_commit).block_on()?;
72	    ses.finish_tx(tx, &format!("commit {}", wc_commit.id().hex()))
73	}
74	
75	/// Snapshot, then rewrite `rev`'s description and rebase its
76	/// descendants (`jj describe -r <rev> -m <desc>`).
77	pub fn describe(repo: &Path, rev: &str, desc: &str) -> Result<()> {
78	    let mut ses = session::RepoSession::open(repo)?;
79	    ses.snapshot()?;
80	    let commit = one_commit(&ses, rev)?;
81	    let desc = complete_newline(desc);
82	    if commit.description() == desc {
83	        return Ok(());
84	    }
85	    let mut tx = ses.start_tx();
86	    tx.repo_mut()
87	        .rewrite_commit(&commit)
88	        .set_description(desc)
89	        .write()
90	        .block_on()?;
91	    tx.repo_mut().rebase_descendants().block_on()?;
92	    ses.finish_tx(tx, &format!("describe commit {}", commit.id().hex()))
93	}
94	
95	/// Snapshot, then point local bookmark `name` at `rev`
96	/// (`jj bookmark set <name> -r <rev>`).
97	pub fn bookmark_set(repo: &Path, name: &str, rev: &str) -> Result<()> {
98	    use jj_lib::op_store::RefTarget;
99	    let mut ses = session::RepoSession::open(repo)?;
100	    ses.snapshot()?;
101	    let commit = one_commit(&ses, rev)?;
102	    let mut tx = ses.start_tx();
103	    tx.repo_mut()
104	        .set_local_bookmark_target(name.as_ref(), RefTarget::normal(commit.id().clone()));
105	    ses.finish_tx(
106	        tx,
107	        &format!("point bookmark {} to commit {}", name, commit.id().hex()),
108	    )
109	}
110	
111	/// Snapshot, then push local bookmark `name` to `origin`
112	/// (`jj git push --bookmark <name>`), force-with-lease against the
113	/// last-seen remote position.
114	///
115	/// Deviation from the CLI: no conflicted / no-description / private
116	/// preflights on the pushed commits; the push callers validate the
117	/// commit they publish before calling.
118	pub fn git_push_bookmark(repo: &Path, name: &str) -> Result<()> {
119	    use jj_lib::git::{GitPushOptions, GitPushRefTargets, GitSettings};
120	    use jj_lib::merge::Diff;
121	    use jj_lib::ref_name::{RefNameBuf, RemoteName};
122	
123	    let mut ses = session::RepoSession::open(repo)?;
124	    ses.snapshot()?;
125	    let remote = RemoteName::new("origin");
126	    let ref_name: RefNameBuf = name.into();
127	    let local = ses
128	        .repo
129	        .view()
130	        .get_local_bookmark(&ref_name)
131	        .as_normal()
132	        .cloned()
133	        .ok_or_else(|| format!("bookmark '{name}' is absent or conflicted"))?;
134	    let remote_ref = ses
135	        .repo
136	        .view()
137	        .get_remote_bookmark(ref_name.to_remote_symbol(remote));
138	    let before = remote_ref.target.as_normal().cloned();
139	    if before.as_ref() == Some(&local) {
140	        return Ok(()); // Already in sync; matches `jj git push` "Nothing changed".
141	    }
142	    let ref_updates = GitPushRefTargets {
143	        bookmarks: vec![(
144	            ref_name.clone(),
145	            Diff {
146	                before,
147	                after: Some(local),
148	            },
149	        )],
150	        tags: vec![],
151	    };
152	    let git_settings = GitSettings::from_settings(&ses.settings)?;
153	    let mut tx = ses.start_tx();
154	    let stats = jj_lib::git::push_refs(
155	        tx.repo_mut(),
156	        git_settings.to_subprocess_options(),
157	        remote,
158	        &ref_updates,
159	        &mut session::DebugCallback,
160	        &GitPushOptions::default(),
161	    )?;
162	    if !stats.all_ok() {
163	        return Err(format!(
164	            "git push of bookmark '{name}' failed: rejected {:?}, remote rejected {:?}",
165	            stats.rejected, stats.remote_rejected
166	        )
167	        .into());
168	    }
169	    ses.finish_tx(tx, &format!("push bookmark {name} to git remote origin"))
170	}
171	
172	/// Snapshot, then fetch all branches from `remote` and import the
173	/// results (`jj git fetch --remote <remote>`). Returns one line per
174	/// changed remote bookmark, empty when the fetch changed nothing.
175	///
176	/// Deviation from the CLI: the branch expression is always "all
177	/// branches" rather than the remote's configured fetch refspecs,
178	/// which is what a standard `origin` resolves to anyway.
179	pub fn git_fetch(repo: &Path, remote: &str) -> Result<Vec<String>> {
180	    use jj_lib::git::{GitFetch, GitFetchRefExpression, GitSettings, expand_fetch_refspecs};
181	    use jj_lib::ref_name::RemoteName;
182	    use jj_lib::str_util::StringExpression;
183	
184	    let mut ses = session::RepoSession::open(repo)?;
185	    ses.snapshot()?;
186	    let remote = RemoteName::new(remote);
187	    let expanded = expand_fetch_refspecs(
188	        remote,
189	        GitFetchRefExpression {
190	            bookmark: StringExpression::all(),
191	            tag: StringExpression::none(),
192	        },
193	    )?;
194	    let git_settings = GitSettings::from_settings(&ses.settings)?;
195	    let import_options = ses.import_options()?;
196	    let mut tx = ses.start_tx();
197	    let mut fetch = GitFetch::new(
198	        tx.repo_mut(),
199	        git_settings.to_subprocess_options(),
200	        &import_options,
201	    )?;
202	    fetch.fetch(remote, expanded, &mut session::DebugCallback, None, None)?;
203	    let stats = fetch.import_refs().block_on()?;
204	    drop(fetch);
205	    let lines: Vec<String> = stats
206	        .changed_remote_bookmarks
207	        .iter()
208	        .map(|(symbol, _)| format!("bookmark {symbol} updated"))
209	        .collect();
210	    if !tx.repo().has_changes() {
211	        return Ok(lines);
212	    }
213	    tx.repo_mut().rebase_descendants().block_on()?;
214	    ses.finish_tx(tx, &format!("fetch from git remote {}", remote.as_str()))?;
215	    Ok(lines)
216	}
217	
218	/// Resolve `rev` against an open engine to exactly one commit.
219	fn one_commit(ses: &session::RepoSession, rev: &str) -> Result<jj_lib::commit::Commit> {
220	    let ids = common::resolve_revset(&ses.workspace, &ses.repo, rev)?;
221	    match ids.as_slice() {
222	        [id] => Ok(ses.repo.store().get_commit(id)?),
223	        other => Err(format!(
224	            "expected exactly one commit for {rev:?}, got {}",
225	            other.len()
226	        )
227	        .into()),
228	    }
229	}
230	
231	/// True when `revset` references a working copy, so the query must
232	/// snapshot before resolving (an op-store write) to see the
233	/// filesystem as it is right now, like the CLI's auto-snapshot.
234	///
235	/// A `@` is working-copy syntax (`@`, `@-`, `ws@`) unless it has
236	/// symbol characters on *both* sides, which is the remote-bookmark
237	/// form (`name@remote`).
238	fn references_working_copy(revset: &str) -> bool {
239	    let is_symbol_char =
240	        |c: char| c.is_ascii_alphanumeric() || matches!(c, '_' | '-' | '.' | '/' | '+');
241	    let chars: Vec<char> = revset.chars().collect();
242	    chars.iter().enumerate().any(|(i, &c)| {
243	        c == '@'
244	            && !(i > 0
245	                && is_symbol_char(chars[i - 1])
246	                && chars.get(i + 1).copied().is_some_and(is_symbol_char))
247	    })
248	}
249	
250	/// Load `repo` for a read of `revset`: a working-copy-relative
251	/// revset snapshots first so "right now" questions answer about the
252	/// filesystem; anything else is a plain read-only load.
253	fn repo_for_read(
254	    repo: &Path,
255	    revset: &str,
256	) -> Result<(
257	    jj_lib::workspace::Workspace,
258	    std::sync::Arc<jj_lib::repo::ReadonlyRepo>,
259	)> {
260	    if references_working_copy(revset) {
261	        let mut ses = session::RepoSession::open(repo)?;
262	        ses.snapshot()?;
263	        Ok((ses.workspace, ses.repo))
264	    } else {
265	        common::load_repo(repo)
266	    }
267	}
268	
269	/// Resolve `revset` in-process and return its commits, in revset
270	/// order (newest first, matching `jj log`).
271	fn commits_of(repo: &Path, revset: &str) -> Result<Vec<Commit>> {
272	    let (workspace, repo_at_head) = repo_for_read(repo, revset)?;
273	    let ids = common::resolve_revset(&workspace, &repo_at_head, revset)?;
274	    ids.iter()
275	        .map(|id| Ok(repo_at_head.store().get_commit(id)?))
276	        .collect()
277	}
278	
279	/// True when `revset` matches at least one commit in `repo`.
280	///
281	/// A valid-but-empty revset (e.g. `conflicts()` on a clean repo)
282	/// is `Ok(false)`; an unresolvable revision is an `Err`, which
283	/// `rev_exists` folds to `false`.
284	pub fn matches(repo: &Path, revset: &str) -> Result<bool> {
285	    let (workspace, repo_at_head) = repo_for_read(repo, revset)?;
286	    Ok(!common::resolve_revset(&workspace, &repo_at_head, revset)?.is_empty())
287	}
288	
289	/// True when `rev` resolves in `repo`.
290	///
291	/// Folds jj's unresolvable-revision error (`is_no_such_revision`,
292	/// either path) to `Ok(false)`; other failures (bad repo path,
293	/// spawn error) stay `Err`.
294	pub fn rev_exists(repo: &Path, rev: &str) -> Result<bool> {
295	    match matches(repo, rev) {
296	        Ok(found) => Ok(found),
297	        Err(e) if is_no_such_revision(e.as_ref()) => Ok(false),
298	        Err(e) => Err(e),
299	    }
300	}
301	
302	/// True when `e` is jj's unresolvable-revision error, the typed
303	/// `RevsetResolutionError::NoSuchRevision` (every rev query is
304	/// in-process now, so the stderr-wording fallback is gone).
305	pub fn is_no_such_revision(e: &(dyn std::error::Error + 'static)) -> bool {
306	    matches!(
307	        e.downcast_ref::<RevsetResolutionError>(),
308	        Some(RevsetResolutionError::NoSuchRevision { .. })
309	    )
310	}
311	
312	/// The 12-character change id of `rev`.
313	pub fn chid_of(repo: &Path, rev: &str) -> Result<String> {
314	    Ok(commits_of(repo, rev)?
315	        .iter()
316	        .map(common::format_chid)
317	        .collect())
318	}
319	
320	/// The full commit id of `rev`.
321	pub fn cid_of(repo: &Path, rev: &str) -> Result<String> {
322	    Ok(commits_of(repo, rev)?
323	        .iter()
324	        .map(|c| c.id().hex())
325	        .collect())
326	}
327	
328	/// The 12-character commit id of `rev`.
329	pub fn cid_short_of(repo: &Path, rev: &str) -> Result<String> {
330	    Ok(cids_short_of(repo, rev)?.concat())
331	}
332	
333	/// 12-character commit ids of every commit `revset` resolves to:
334	/// the multi-result sibling of `cid_short_of` (e.g. the heads of a
335	/// conflicted bookmark).
336	pub fn cids_short_of(repo: &Path, revset: &str) -> Result<Vec<String>> {
337	    Ok(commits_of(repo, revset)?
338	        .iter()
339	        .map(|c| {
340	            let hex = c.id().hex();
341	            hex[..hex.len().min(12)].to_string()
342	        })
343	        .collect())
344	}
345	
346	/// The full description (title + body) of `rev`, surrounding
347	/// whitespace trimmed (the shape the spawned `-T description` form
348	/// returned, which every caller still expects).
349	pub fn desc_of(repo: &Path, rev: &str) -> Result<String> {
350	    let all: String = commits_of(repo, rev)?
351	        .iter()
352	        .map(|c| c.description())
353	        .collect();
354	    Ok(all.trim().to_string())
355	}
356	
357	/// True when `rev` is empty (no file changes relative to its
358	/// parent). Strict: exactly one commit must resolve.
359	pub fn is_empty(repo: &Path, rev: &str) -> Result<bool> {
360	    let (workspace, repo_at_head) = repo_for_read(repo, rev)?;
361	    let ids = common::resolve_revset(&workspace, &repo_at_head, rev)?;
362	    match ids.as_slice() {
363	        [id] => {
364	            let commit = repo_at_head.store().get_commit(id)?;
365	            Ok(commit.is_empty(repo_at_head.as_ref()).block_on()?)
366	        }
367	        other => Err(format!(
368	            "jj::is_empty: expected exactly one commit for {rev:?}, got {}",
369	            other.len()
370	        )
371	        .into()),
372	    }
373	}
374	
375	/// Run `jj bookmark list <bookmark> -R <repo>` and return its
376	/// stdout, which is empty when the local bookmark doesn't exist.
377	pub fn bookmark_list(repo: &Path, bookmark: &str) -> Result<String> {
378	    common::run(
379	        "jj",
380	        &["bookmark", "list", bookmark, "-R", &repo.to_string_lossy()],
381	        Path::new("."),
382	    )
383	}
384	
385	/// Like `bookmark_list` but with `-a`: includes remote refs,
386	/// tracked ones indented (`  @origin: ...`), non-tracking at
387	/// column 0 (`<bookmark>@<remote>: ...`). The input for
388	/// `common::find_tracked_remote` /
389	/// `common::find_non_tracking_remote`.
390	pub fn bookmark_list_all(repo: &Path, bookmark: &str) -> Result<String> {
391	    common::run(
392	        "jj",
393	        &[
394	            "bookmark",
395	            "list",
396	            "-a",
397	            bookmark,
398	            "-R",
399	            &repo.to_string_lossy(),
400	        ],
401	        Path::new("."),
402	    )
403	}
