405	#[cfg(test)]
406	mod tests {
407	    use super::*;
408	    use crate::test_helpers::{self, Fixture, jj_ok};
409	
410	    /// `git rev-parse <rev>` in a fixture repo (test inspection of
411	    /// the colocated git side).
412	    fn git_rev_parse(repo: &std::path::Path, rev: &str) -> String {
413	        let out = std::process::Command::new("git")
414	            .args(["rev-parse", rev])
415	            .current_dir(repo)
416	            .output()
417	            .expect("spawn git");
418	        assert!(out.status.success(), "git rev-parse {rev} failed");
419	        String::from_utf8_lossy(&out.stdout).trim().to_string()
420	    }
421	
422	    /// In-process commit: description lands on `@-`, a fresh empty
423	    /// `@` opens, and the colocated git HEAD follows.
424	    #[test]
425	    fn in_process_commit_updates_colocated_git() {
426	        let fx = Fixture::new("jjmut");
427	        std::fs::write(fx.work.join("mut.txt"), "hello").unwrap();
428	        commit(&fx.work, "test: in-process commit\n\nbody line").unwrap();
429	        assert_eq!(
430	            desc_of(&fx.work, "@-").unwrap(),
431	            "test: in-process commit\n\nbody line"
432	        );
433	        assert!(is_empty(&fx.work, "@").unwrap());
434	        assert_eq!(
435	            git_rev_parse(&fx.work, "HEAD"),
436	            cid_of(&fx.work, "@-").unwrap()
437	        );
438	    }
439	
440	    /// In-process bookmark set exports the ref to the colocated git
441	    /// repo, and describe rewrites reach both sides.
442	    #[test]
443	    fn in_process_bookmark_and_describe_export_to_git() {
444	        let fx = Fixture::new("jjmutbm");
445	        bookmark_set(&fx.work, "bmtest", "@-").unwrap();
446	        assert_eq!(
447	            git_rev_parse(&fx.work, "refs/heads/bmtest"),
448	            cid_of(&fx.work, "@-").unwrap()
449	        );
450	        describe(&fx.work, "@-", "test: rewritten description").unwrap();
451	        assert_eq!(
452	            desc_of(&fx.work, "@-").unwrap(),
453	            "test: rewritten description"
454	        );
455	        assert_eq!(
456	            git_rev_parse(&fx.work, "refs/heads/bmtest"),
457	            cid_of(&fx.work, "@-").unwrap()
458	        );
459	    }
460	
461	    /// A working-copy read sees the filesystem as it is right now:
462	    /// the snapshot-first path is live, not the stale op-store view.
463	    #[test]
464	    fn wc_relative_reads_snapshot_first() {
465	        let fx = Fixture::new("jjwcsnap");
466	        assert!(is_empty(&fx.work, "@").unwrap());
467	        std::fs::write(fx.work.join("wcsnap.txt"), "x").unwrap();
468	        assert!(!is_empty(&fx.work, "@").unwrap());
469	    }
470	
471	    /// Working-copy forms route to the snapshot-first path.
472	    #[test]
473	    fn working_copy_revsets_are_detected() {
474	        assert!(references_working_copy("@"));
475	        assert!(references_working_copy("@-"));
476	        assert!(references_working_copy("@ & empty()"));
477	        assert!(references_working_copy("::@"));
478	        assert!(references_working_copy("ws@"));
479	        assert!(references_working_copy("abc123::(@-)"));
480	    }
481	
482	    /// Remote-bookmark forms and plain revsets stay in-process.
483	    #[test]
484	    fn non_working_copy_revsets_are_not_detected() {
485	        assert!(!references_working_copy("main"));
486	        assert!(!references_working_copy("conflicts()"));
487	        assert!(!references_working_copy("bookmarks(exact:main)"));
488	        assert!(!references_working_copy("feature@origin"));
489	        assert!(!references_working_copy("present(refactor-vc-x1@origin)"));
490	        assert!(!references_working_copy("abc123::main"));
491	    }
492	
493	    /// The in-process id/description accessors agree with the
494	    /// spawned `jj log` templates on the same commit.
495	    #[test]
496	    fn in_process_reads_match_spawned_jj() {
497	        let fx = Fixture::new("jjreads");
498	        // Pin `@-` to its concrete commit id so every query below
499	        // is a non-`@` revset (the in-process path under test).
500	        let rev = test_helpers::cid(&fx.work, "@-");
501	        assert_eq!(cid_short_of(&fx.work, &rev).unwrap(), rev);
502	        assert!(cid_of(&fx.work, &rev).unwrap().starts_with(&rev));
503	        assert_eq!(
504	            chid_of(&fx.work, &rev).unwrap(),
505	            test_helpers::chid(&fx.work, "@-")
506	        );
507	        assert_eq!(
508	            desc_of(&fx.work, &rev).unwrap(),
509	            test_helpers::description(&fx.work, "@-")
510	        );
511	        let expected_empty =
512	            jj_ok(&fx.work, &["log", "-r", &rev, "--no-graph", "-T", "empty"]) == "true";
513	        assert_eq!(is_empty(&fx.work, &rev).unwrap(), expected_empty);
514	    }
515	
516	    /// `matches` / `rev_exists` in-process: valid-but-empty is
517	    /// `false`, unresolvable folds to `false` via the typed
518	    /// `NoSuchRevision`, and a real commit id resolves.
519	    #[test]
520	    fn matches_and_rev_exists_in_process() {
521	        let fx = Fixture::new("jjexists");
522	        let rev = test_helpers::cid(&fx.work, "@-");
523	        assert!(!matches(&fx.work, "conflicts()").unwrap());
524	        assert!(rev_exists(&fx.work, &rev).unwrap());
525	        assert!(!rev_exists(&fx.work, "no-such-bookmark-xyz").unwrap());
526	    }
527	
528	    /// `cids_short_of` returns one id per matching commit, exactly
529	    /// the bookmark-heads shape `sync` consumes.
530	    #[test]
531	    fn cids_short_of_returns_bookmark_heads() {
532	        let fx = Fixture::new("jjheads");
533	        let rev = test_helpers::cid(&fx.work, "@-");
534	        jj_ok(&fx.work, &["bookmark", "set", "testbm", "-r", &rev]);
535	        assert_eq!(
536	            cids_short_of(&fx.work, "bookmarks(exact:testbm)").unwrap(),
537	            vec![rev]
538	        );
539	        assert!(
540	            cids_short_of(&fx.work, "bookmarks(exact:absentbm)")
541	                .unwrap()
542	                .is_empty()
543	        );
544	    }
545	}
