1	//! `RepoSession`: an in-process working session with one repo.
2	//!
3	//! The plumbing jj's own CLI wraps around every mutation
4	//! (`WorkspaceCommandHelper` in jj-cli), reduced to what the facade's
5	//! verbs need: user-config-backed settings, the working-copy snapshot
6	//! cycle, and transaction finish. The reference implementation is jj
7	//! 0.43's `cli_util.rs`; deviations are documented on each function.
8	//! The name is backend-neutral on purpose: what a session holds and
9	//! its open -> mutate -> finish lifecycle would survive a non-jj
10	//! backend.
11	//!
12	//! - `RepoSession::open`: settings + workspace + repo-at-head, colocation
13	//!   detected.
14	//! - `RepoSession::snapshot`: the CLI's `maybe_snapshot`: git head/refs
15	//!   import around a working-copy snapshot, under the same lock file
16	//!   the CLI takes.
17	//! - `RepoSession::finish_tx`: the CLI's `finish_transaction`: git HEAD
18	//!   reset + ref export, op-store commit, working-copy update.
19	
20	use std::collections::HashMap;
21	use std::path::{Path, PathBuf};
22	use std::sync::Arc;
23	
24	use jj_lib::commit::Commit;
25	use jj_lib::config::{ConfigLayer, ConfigSource, StackedConfig};
26	use jj_lib::fileset::{self, FilesetDiagnostics, FilesetParseContext};
27	use jj_lib::git::{self, GitImportOptions, GitSettings};
28	use jj_lib::gitignore::GitIgnoreFile;
29	use jj_lib::lock::FileLock;
30	use jj_lib::matchers::NothingMatcher;
31	use jj_lib::repo::{ReadonlyRepo, Repo, StoreFactories};
32	use jj_lib::repo_path::{RepoPath, RepoPathUiConverter};
33	use jj_lib::settings::{HumanByteSize, UserSettings};
34	use jj_lib::transaction::Transaction;
35	use jj_lib::working_copy::{SnapshotOptions, WorkingCopyFreshness};
36	use jj_lib::workspace::{Workspace, default_working_copy_factories};
37	use log::debug;
38	use pollster::FutureExt;
39	
40	/// Crate-standard boxed-error result, aliased locally for brevity.
41	type Result<T> = std::result::Result<T, Box<dyn std::error::Error>>;
42	
43	/// One repo opened for mutation: workspace, repo at head, settings,
44	/// and whether the workspace is colocated with git.
45	pub struct RepoSession {
46	    /// The loaded workspace (owns the working copy).
47	    pub workspace: Workspace,
48	    /// The repo, loaded at (or advanced past) the op-store head.
49	    pub repo: Arc<ReadonlyRepo>,
50	    /// Settings from the user's real jj config (see `stacked_config`).
51	    pub settings: UserSettings,
52	    /// True when `.git` and the working copy are shared with git, so
53	    /// mutations must import from and export to the git side.
54	    pub colocated: bool,
55	}
56	
57	/// Load the user's jj configuration the way the jj CLI does.
58	///
59	/// Layers, lowest to highest: jj-lib defaults, `/etc/jj` (unix),
60	/// `$JJ_CONFIG` (overrides system and user paths) or the user files
61	/// (`~/.jjconfig.toml`, `<config dir>/jj/config.toml` + `conf.d`),
62	/// the repo config (`.jj/repo/config.toml`), then `JJ_USER` /
63	/// `JJ_EMAIL` overrides. Deviation from the CLI: no command-line
64	/// layer and no `EnvBase` layer (debug / color / pager knobs that
65	/// only affect CLI presentation).
66	fn stacked_config(repo_config_path: Option<&Path>) -> Result<StackedConfig> {
67	    let mut config = StackedConfig::with_defaults();
68	    // Keys the engine reads whose defaults ship with the jj CLI's
69	    // config files rather than jj-lib's (values match jj 0.43).
70	    config.add_layer(ConfigLayer::parse(
71	        ConfigSource::Default,
72	        r#"
73	        [snapshot]
74	        auto-track = "all()"
75	        max-new-file-size = "1MiB"
76	        [git]
77	        auto-local-bookmark = false
78	        "#,
79	    )?);
80	    let jj_config = std::env::var("JJ_CONFIG").ok();
81	
82	    if jj_config.is_none() && cfg!(unix) {
83	        load_file_if_exists(&mut config, ConfigSource::System, "/etc/jj/config.toml")?;
84	        load_dir_if_exists(&mut config, ConfigSource::System, "/etc/jj/conf.d")?;
85	    }
86	
87	    if let Some(paths) = &jj_config {
88	        for path in std::env::split_paths(paths).filter(|p| !p.as_os_str().is_empty()) {
89	            if path.is_dir() {
90	                config.load_dir(ConfigSource::User, path)?;
91	            } else {
92	                config.load_file(ConfigSource::User, path)?;
93	            }
94	        }
95	    } else {
96	        let home = std::env::var_os("HOME").map(PathBuf::from);
97	        let config_dir = match std::env::var_os("XDG_CONFIG_HOME") {
98	            Some(x) if !x.is_empty() => Some(PathBuf::from(x)),
99	            _ => home.as_ref().map(|h| h.join(".config")),
100	        };
101	        if let Some(home) = &home {
102	            load_file_if_exists(&mut config, ConfigSource::User, home.join(".jjconfig.toml"))?;
103	        }
104	        if let Some(dir) = &config_dir {
105	            load_file_if_exists(&mut config, ConfigSource::User, dir.join("jj/config.toml"))?;
106	            load_dir_if_exists(&mut config, ConfigSource::User, dir.join("jj/conf.d"))?;
107	        }
108	    }
109	
110	    if let Some(repo_path) = repo_config_path {
111	        load_file_if_exists(
112	            &mut config,
113	            ConfigSource::Repo,
114	            repo_path.join("config.toml"),
115	        )?;
116	    }
117	
118	    let mut env = ConfigLayer::empty(ConfigSource::EnvOverrides);
119	    if let Ok(value) = std::env::var("JJ_USER") {
120	        env.set_value("user.name", value)?;
121	    }
122	    if let Ok(value) = std::env::var("JJ_EMAIL") {
123	        env.set_value("user.email", value)?;
124	    }
125	    if !env.is_empty() {
126	        config.add_layer(env);
127	    }
128	    Ok(config)
129	}
130	
131	/// Add one config file as a layer when it exists.
132	fn load_file_if_exists(
133	    config: &mut StackedConfig,
134	    source: ConfigSource,
135	    path: impl Into<PathBuf>,
136	) -> Result<()> {
137	    let path = path.into();
138	    if path.is_file() {
139	        config.load_file(source, path)?;
140	    }
141	    Ok(())
142	}
143	
144	/// Add one config directory as a layer set when it exists.
145	fn load_dir_if_exists(
146	    config: &mut StackedConfig,
147	    source: ConfigSource,
148	    path: impl Into<PathBuf>,
149	) -> Result<()> {
150	    let path = path.into();
151	    if path.is_dir() {
152	        config.load_dir(source, path)?;
153	    }
154	    Ok(())
155	}
156	
157	/// True when the workspace shares its working copy with a colocated
158	/// git repo (jj-cli's `is_colocated_git_workspace`, minus the
159	/// canonicalized `.git`-symlink fallback: vc-x1 lays repos out with
160	/// a real `.git` directory).
161	fn is_colocated(workspace: &Workspace, repo: &Arc<ReadonlyRepo>) -> bool {
162	    let Ok(backend) = git::get_git_backend(repo.store()) else {
163	        return false;
164	    };
165	    let Some(git_workdir) = backend.git_workdir() else {
166	        return false;
167	    };
168	    if git_workdir == workspace.workspace_root() {
169	        return true;
170	    }
171	    let Ok(dot_git) = workspace.workspace_root().join(".git").canonicalize() else {
172	        return false;
173	    };
174	    git_workdir.canonicalize().ok().as_deref() == dot_git.parent()
175	}
176	
177	impl RepoSession {
178	    /// Open `path` for mutation: user settings, workspace, repo at
179	    /// the op-store head, colocation flag.
180	    pub fn open(path: &Path) -> Result<Self> {
181	        // Two-phase settings: the repo config layer lives under
182	        // `.jj/repo`, whose location the loaded workspace knows.
183	        let settings = UserSettings::from_config(stacked_config(None)?)?;
184	        let store_factories = StoreFactories::default();
185	        let working_copy_factories = default_working_copy_factories();
186	        let workspace =
187	            Workspace::load(&settings, path, &store_factories, &working_copy_factories)?;
188	        let settings = UserSettings::from_config(stacked_config(Some(workspace.repo_path()))?)?;
189	        let workspace =
190	            Workspace::load(&settings, path, &store_factories, &working_copy_factories)?;
191	        let repo = workspace.repo_loader().load_at_head().block_on()?;
192	        let colocated = is_colocated(&workspace, &repo);
193	        Ok(RepoSession {
194	            workspace,
195	            repo,
196	            settings,
197	            colocated,
198	        })
199	    }
200	
201	    /// Take the git import/export lock the CLI takes around its
202	    /// import/snapshot/export cycle; `None` when not colocated.
203	    fn lock_git(&self) -> Result<Option<FileLock>> {
204	        if !self.colocated {
205	            return Ok(None);
206	        }
207	        let path = self.workspace.repo_path().join("git_import_export.lock");
208	        Ok(Some(FileLock::lock(path)?))
209	    }
210	
211	    /// The CLI's `maybe_snapshot`: import git HEAD, snapshot the
212	    /// working copy, import git refs, each its own operation.
213	    pub fn snapshot(&mut self) -> Result<()> {
214	        let _lock = self.lock_git()?;
215	        if self.colocated {
216	            // Reload under the lock: another process may have
217	            // committed an operation while we waited.
218	            self.repo = self.workspace.repo_loader().load_at_head().block_on()?;
219	            self.import_git_head()?;
220	        }
221	        self.snapshot_working_copy()?;
222	        if self.colocated {
223	            self.import_git_refs()?;
224	        }
225	        Ok(())
226	    }
227	
228	    /// Import a moved git HEAD (someone ran plain git here): check
229	    /// out the new head and reset the working-copy state to it.
230	    fn import_git_head(&mut self) -> Result<()> {
231	        let mut tx = self.repo.start_transaction();
232	        git::import_head(tx.repo_mut()).block_on()?;
233	        if !tx.repo().has_changes() {
234	            return Ok(());
235	        }
236	        debug!("git HEAD moved; importing");
237	        let new_git_head = tx.repo().view().git_head().clone();
238	        if let Some(new_git_head_id) = new_git_head.as_normal() {
239	            let name = self.workspace.workspace_name().to_owned();
240	            let head_commit = tx.repo().store().get_commit(new_git_head_id)?;
241	            let wc_commit = tx.repo_mut().check_out(name, &head_commit).block_on()?;
242	            let mut locked_ws = self.workspace.start_working_copy_mutation().block_on()?;
243	            // The git command that moved HEAD updated the files too,
244	            // so reset the state without touching the working copy.
245	            locked_ws.locked_wc().reset(&wc_commit).block_on()?;
246	            tx.repo_mut().rebase_descendants().block_on()?;
247	            self.repo = tx.commit("import git head").block_on()?;
248	            locked_ws.finish(self.repo.op_id().clone()).block_on()?;
249	        } else {
250	            tx.repo_mut().rebase_descendants().block_on()?;
251	            self.repo = tx.commit("import git head").block_on()?;
252	        }
253	        Ok(())
254	    }
255	
256	    /// Snapshot the working copy into the wc commit if the tree
257	    /// changed (the CLI's `snapshot_working_copy`).
258	    ///
259	    /// Deviation: no immutable-wc-commit branch. vc-x1 never edits
260	    /// an immutable commit, and evaluating `immutable_heads()` needs
261	    /// the CLI's revset-alias machinery.
262	    fn snapshot_working_copy(&mut self) -> Result<()> {
263	        let name = self.workspace.workspace_name().to_owned();
264	        let repo = self.repo.clone();
265	
266	        let auto_track_pattern = self.settings.get_string("snapshot.auto-track")?;
267	        let mut diagnostics = FilesetDiagnostics::new();
268	        let root = self.workspace.workspace_root().to_path_buf();
269	        let path_converter = RepoPathUiConverter::Fs {
270	            cwd: root.clone(),
271	            base: root,
272	        };
273	        let fileset_aliases = jj_lib::fileset::FilesetAliasesMap::new();
274	        let fileset_ctx = FilesetParseContext {
275	            aliases_map: &fileset_aliases,
276	            path_converter: &path_converter,
277	        };
278	        let auto_track =
279	            fileset::parse(&mut diagnostics, &auto_track_pattern, &fileset_ctx)?.to_matcher();
280	        let HumanByteSize(mut max_new_file_size) = self
281	            .settings
282	            .get_value_with("snapshot.max-new-file-size", TryInto::try_into)?;
283	        if max_new_file_size == 0 {
284	            max_new_file_size = u64::MAX;
285	        }
286	        let options = SnapshotOptions {
287	            base_ignores: self.base_ignores()?,
288	            progress: None,
289	            start_tracking_matcher: auto_track.as_ref(),
290	            force_tracking_matcher: &NothingMatcher,
291	            max_new_file_size,
292	        };
293	
294	        let mut locked_ws = self.workspace.start_working_copy_mutation().block_on()?;
295	        let Some(wc_commit_id) = repo.view().get_wc_commit_id(&name).cloned() else {
296	            return Ok(()); // Workspace deleted from the repo view.
297	        };
298	        let mut wc_commit = repo.store().get_commit(&wc_commit_id)?;
299	        match WorkingCopyFreshness::check_stale(locked_ws.locked_wc(), &wc_commit, &repo)
300	            .block_on()?
301	        {
302	            WorkingCopyFreshness::Fresh => {}
303	            WorkingCopyFreshness::Updated(wc_operation) => {
304	                self.repo = repo.reload_at(&wc_operation).block_on()?;
305	                let Some(id) = self.repo.view().get_wc_commit_id(&name).cloned() else {
306	                    return Ok(());
307	                };
308	                wc_commit = self.repo.store().get_commit(&id)?;
309	            }
310	            stale => {
311	                return Err(format!(
312	                    "the working copy is stale ({stale:?}); run `jj workspace update-stale` \
313	                     in {}",
314	                    self.workspace.workspace_root().display()
315	                )
316	                .into());
317	            }
318	        }
319	
320	        let (new_tree, _stats) = locked_ws.locked_wc().snapshot(&options).block_on()?;
321	        if new_tree.tree_ids_and_labels() != wc_commit.tree().tree_ids_and_labels() {
322	            debug!("working-copy tree changed; committing snapshot operation");
323	            let mut tx = self.repo.start_transaction();
324	            tx.set_is_snapshot(true);
325	            let mut_repo = tx.repo_mut();
326	            let new_wc_commit = mut_repo
327	                .rewrite_commit(&wc_commit)
328	                .set_tree(new_tree.clone())
329	                .write()
330	                .block_on()?;
331	            mut_repo.set_wc_commit(name.clone(), new_wc_commit.id().clone())?;
332	            mut_repo.rebase_descendants().block_on()?;
333	            if self.colocated {
334	                git::update_intent_to_add(
335	                    mut_repo.base_repo().as_ref(),
336	                    &wc_commit.tree(),
337	                    &new_wc_commit.tree(),
338	                )
339	                .block_on()?;
340	                git::export_refs(mut_repo)?;
341	            }
342	            self.repo = tx.commit("snapshot working copy").block_on()?;
343	        }
344	        locked_ws.finish(self.repo.op_id().clone()).block_on()?;
345	        Ok(())
346	    }
347	
348	    /// Import git refs (fetch results, refs moved by plain git) and
349	    /// rebase descendants of rewritten commits.
350	    fn import_git_refs(&mut self) -> Result<()> {
351	        let import_options = self.import_options()?;
352	        let mut tx = self.repo.start_transaction();
353	        git::import_refs(tx.repo_mut(), &import_options).block_on()?;
354	        if !tx.repo().has_changes() {
355	            return Ok(());
356	        }
357	        debug!("git refs changed; importing");
358	        tx.repo_mut().rebase_descendants().block_on()?;
359	        self.finish_tx(tx, "import git refs")
360	    }
361	
362	    /// Build `GitImportOptions` from settings.
363	    ///
364	    /// Deviation from the CLI: the per-remote auto-track map is
365	    /// driven by `git.auto-local-bookmark` alone, not the per-remote
366	    /// `remotes.<name>.auto-track-bookmarks` patterns.
367	    pub fn import_options(&self) -> Result<GitImportOptions> {
368	        let git_settings = GitSettings::from_settings(&self.settings)?;
369	        let auto_local_bookmark = self.settings.get_bool("git.auto-local-bookmark")?;
370	        let mut remote_auto_track_bookmarks = HashMap::new();
371	        if auto_local_bookmark {
372	            for remote in git::get_all_remote_names(self.repo.store())? {
373	                remote_auto_track_bookmarks.insert(
374	                    remote,
375	                    jj_lib::str_util::StringExpression::all().to_matcher(),
376	                );
377	            }
378	        }
379	        Ok(GitImportOptions {
380	            abandon_unreachable_commits: git_settings.abandon_unreachable_commits,
381	            record_synthetic_predecessors: git_settings.record_synthetic_predecessors,
382	            remote_auto_track_bookmarks,
383	        })
384	    }
385	
386	    /// The gitignore chain snapshots respect: the user's global
387	    /// excludes file, then the git dir's `info/exclude`.
388	    fn base_ignores(&self) -> Result<Arc<GitIgnoreFile>> {
389	        let mut ignores = GitIgnoreFile::empty();
390	        let Ok(backend) = git::get_git_backend(self.repo.store()) else {
391	            return Ok(ignores);
392	        };
393	        let git_repo = backend.git_repo();
394	        let excludes = {
395	            let config = git_repo.config_snapshot();
396	            match config.string("core.excludesFile") {
397	                Some(value) => str::from_utf8(&value)
398	                    .ok()
399	                    .map(jj_lib::file_util::expand_home_path)
400	                    .map(|p| self.workspace.workspace_root().join(p)),
401	                None => {
402	                    let config_dir = match std::env::var_os("XDG_CONFIG_HOME") {
403	                        Some(x) if !x.is_empty() => Some(PathBuf::from(x)),
404	                        _ => std::env::var_os("HOME").map(|h| PathBuf::from(h).join(".config")),
405	                    };
406	                    config_dir.map(|d| d.join("git").join("ignore"))
407	                }
408	            }
409	        };
410	        if let Some(path) = excludes {
411	            ignores = ignores.chain_with_file(RepoPath::root(), path)?;
412	        }
413	        ignores = ignores.chain_with_file(
414	            RepoPath::root(),
415	            backend.git_repo_path().join("info/exclude"),
416	        )?;
417	        Ok(ignores)
418	    }
419	
420	    /// Start a transaction stamped with this workspace's name.
421	    pub fn start_tx(&self) -> Transaction {
422	        let mut tx = self.repo.start_transaction();
423	        tx.set_workspace_name(self.workspace.workspace_name());
424	        tx
425	    }
426	
427	    /// The CLI's `finish_transaction`: reset git HEAD and export
428	    /// refs (colocated), commit the operation, update the working
429	    /// copy to the possibly-rewritten wc commit.
430	    pub fn finish_tx(&mut self, mut tx: Transaction, desc: &str) -> Result<()> {
431	        if !tx.repo().has_changes() {
432	            debug!("{desc}: nothing changed");
433	            return Ok(());
434	        }
435	        tx.repo_mut().rebase_descendants().block_on()?;
436	        let name = self.workspace.workspace_name().to_owned();
437	        let old_wc_commit = tx
438	            .base_repo()
439	            .view()
440	            .get_wc_commit_id(&name)
441	            .map(|id| tx.base_repo().store().get_commit(id))
442	            .transpose()?;
443	        let new_wc_commit_id = tx.repo().view().get_wc_commit_id(&name).cloned();
444	
445	        if self.colocated {
446	            if let Some(id) = &new_wc_commit_id {
447	                let wc_commit = tx.repo().store().get_commit(id)?;
448	                git::reset_head(tx.repo_mut(), &wc_commit).block_on()?;
449	            }
450	            git::export_refs(tx.repo_mut())?;
451	        }
452	
453	        self.repo = tx.commit(desc).block_on()?;
454	
455	        if let Some(id) = &new_wc_commit_id {
456	            let new_wc_commit = self.repo.store().get_commit(id)?;
457	            let old_tree = old_wc_commit.as_ref().map(|c| c.tree());
458	            self.workspace
459	                .check_out(self.repo.op_id().clone(), old_tree.as_ref(), &new_wc_commit)
460	                .block_on()?;
461	        }
462	        Ok(())
463	    }
464	
465	    /// The working-copy commit of this workspace.
466	    pub fn wc_commit(&self) -> Result<Commit> {
467	        let name = self.workspace.workspace_name();
468	        let id = self
469	            .repo
470	            .view()
471	            .get_wc_commit_id(name)
472	            .ok_or_else(|| format!("workspace {name:?} has no working-copy commit"))?;
473	        Ok(self.repo.store().get_commit(id)?)
474	    }
475	}
476	
477	/// Callback for jj-lib's git subprocess: no progress requests,
478	/// sideband chatter forwarded to `debug!` (the same place `run`
479	/// put spawned jj's stderr).
480	pub struct DebugCallback;
481	
482	impl git::GitSubprocessCallback for DebugCallback {
483	    /// Progress reporting is not requested.
484	    fn needs_progress(&self) -> bool {
485	        false
486	    }
487	
488	    /// Ignore progress events (never requested).
489	    fn progress(&mut self, _progress: &git::GitProgress) -> std::io::Result<()> {
490	        Ok(())
491	    }
492	
493	    /// Log local git messages at debug, like spawned-jj stderr was.
494	    fn local_sideband(
495	        &mut self,
496	        message: &[u8],
497	        _term: Option<git::GitSidebandLineTerminator>,
498	    ) -> std::io::Result<()> {
499	        debug!("git: {}", String::from_utf8_lossy(message));
500	        Ok(())
501	    }
502	
503	    /// Log remote sideband messages at debug.
504	    fn remote_sideband(
505	        &mut self,
506	        message: &[u8],
507	        _term: Option<git::GitSidebandLineTerminator>,
508	    ) -> std::io::Result<()> {
509	        debug!("remote: {}", String::from_utf8_lossy(message));
510	        Ok(())
511	    }
512	}
