1	//! `push` subcommand — collapse the dual-repo commit+push+
2	//! squash-push ceremony into a single command.
3	//!
4	//! See `notes/chores/chores-05.md > Add push subcommand (0.37.0)` for the
5	//! original design.
6	//!
7	//! The run is a straight line: review → message → commit-work →
8	//! commit-bot → bookmark-set → push-work → squash-push-bot. There
9	//! is no saved state and no resume, because a recorded position
10	//! describes a world that may have changed for reasons push cannot
11	//! know. What push owes instead is that **rerunning is always
12	//! safe**: every stage checks its own precondition and no-ops when
13	//! its work is already done, so a rerun after a failure is simply a
14	//! run.
15	//!
16	//! Failures before `push-work` are rolled back from `jj op`
17	//! snapshots taken moments earlier in this same process. Failures
18	//! from `push-work` on have crossed the remote boundary — push
19	//! stops and reports, and putting the repos right is the user's
20	//! call, not something a tool can infer.
21	
22	use std::fs;
23	use std::io::IsTerminal;
24	use std::path::{Path, PathBuf};
25	
26	use clap::Args;
27	use log::{debug, info, warn};
28	
29	use crate::common::{prompt, run};
30	use crate::context::Context;
31	use crate::jj;
32	use crate::options_flags::squash::SquashSpec;
33	use crate::subcommand::SubcommandRunner;
34	use crate::sync::{current_op_id, op_restore};
35	
36	/// Bookmark the bot (`.claude`) repo always advances and
37	/// pushes. The bot repo is a linear journal on `main` by
38	/// design — `<bookmark>` names a work-repo bookmark only.
39	const BOT_BOOKMARK: &str = "main";
40	
41	/// CLI arguments for the `push` subcommand.
42	///
43	/// Flag set mirrors the design in `notes/chores/chores-05.md`. Flags are
44	/// parsed in 0.37.0-0; their real effects land across the remaining
45	/// 0.37.0-N steps. See the module docstring for which flags activate
46	/// when.
47	#[derive(Args, Debug)]
48	pub struct PushArgs {
49	    /// Bookmark to advance in the work repo (positional form of
50	    /// `--bookmark`). The bot repo always advances `main`.
51	    ///
52	    /// Accepting a positional lets the common case read as `vc-x1 push main`
53	    /// without the `--bookmark` ceremony; `--bookmark` is kept as an
54	    /// alias for scripts and for composition with other args. The two
55	    /// forms conflict if both supplied.
56	    #[arg(value_name = "BOOKMARK", conflicts_with = "bookmark")]
57	    pub bookmark_pos: Option<String>,
58	
59	    /// Bookmark to advance in the work repo (flag form; see positional).
60	    #[arg(long, conflicts_with = "bookmark_pos")]
61	    pub bookmark: Option<String>,
62	
63	    /// Pause between every stage for an interactive approval gate.
64	    #[arg(long)]
65	    pub step: bool,
66	
67	    /// Stop before `squash-push-bot` so it can be run manually.
68	    #[arg(long)]
69	    pub no_squash_push: bool,
70	
71	    /// Print the exact commands for every stage without side effects.
72	    #[arg(long)]
73	    pub dry_run: bool,
74	
75	    /// Commit title (skip `$EDITOR` for the message stage).
76	    #[arg(long, value_name = "STR")]
77	    pub title: Option<String>,
78	
79	    /// Commit body (skip `$EDITOR` for the message stage).
80	    #[arg(long, value_name = "STR")]
81	    pub body: Option<String>,
82	
83	    /// Auto-approve interactive prompts (review gate, message-edit
84	    /// confirmation). Required when `--title` / `--body` aren't both
85	    /// supplied in non-interactive contexts.
86	    #[arg(short = 'y', long)]
87	    pub yes: bool,
88	}
89	
90	/// Inputs to the push op, flat, owned, clap-free.
91	///
92	/// Mirrors `PushArgs`, with the two clap bookmark spellings
93	/// (positional `BOOKMARK` and `--bookmark`) collapsed into one
94	/// `bookmark` field. The rest map straight over: `step`,
95	/// `no_squash_push`, `dry_run`, `title`, `body`, `yes`.
96	pub struct PushParams {
97	    pub bookmark: Option<String>,
98	    pub step: bool,
99	    pub no_squash_push: bool,
100	    pub dry_run: bool,
101	    pub title: Option<String>,
102	    pub body: Option<String>,
103	    pub yes: bool,
104	}
105	
106	/// What the message stage resolves and the later stages consume.
107	///
108	/// Lives for one run in one process — the deliberate replacement
109	/// for the persisted `PushState`. Both chids are captured before
110	/// any commit happens, so each repo's `ochid:` trailer can name the
111	/// other side's change.
112	struct Run {
113	    title: String,
114	    body: String,
115	    /// Chid of the work-repo change this run publishes: `@` when the
116	    /// working copy has changes (it becomes `@-` once committed),
117	    /// else the existing `@-`.
118	    work_chid: String,
119	    /// Same rule on the bot side.
120	    bot_chid: String,
121	    /// Whether the bot working copy had changes — decides whether
122	    /// `commit-bot` runs.
123	    bot_had_changes: bool,
124	}
125	
126	/// `jj op` ids captured immediately before the first mutation, used
127	/// to restore both repos if a pre-remote stage fails.
128	pub(crate) struct Snapshots {
129	    pub(crate) work: String,
130	    pub(crate) bot: String,
131	}
132	
133	impl From<&PushArgs> for PushParams {
134	    /// Convert clap-derived `PushArgs` into the flat `PushParams`,
135	    /// collapsing `bookmark_pos` / `bookmark` (clap already enforces
136	    /// they don't both appear) into the single `bookmark` field.
137	    fn from(a: &PushArgs) -> Self {
138	        Self {
139	            bookmark: a.bookmark_pos.clone().or_else(|| a.bookmark.clone()),
140	            step: a.step,
141	            no_squash_push: a.no_squash_push,
142	            dry_run: a.dry_run,
143	            title: a.title.clone(),
144	            body: a.body.clone(),
145	            yes: a.yes,
146	        }
147	    }
148	}
149	
150	impl SubcommandRunner for PushArgs {
151	    type Params = PushParams;
152	
153	    /// Delegate to the existing `From<&PushArgs>` impl above
154	    /// (total — never fails).
155	    fn to_params(&self) -> Result<Self::Params, String> {
156	        Ok(PushParams::from(self))
157	    }
158	
159	    /// Run the existing `push` op.
160	    fn run(ctx: &Context, params: &Self::Params) -> Result<(), Box<dyn std::error::Error>> {
161	        push(ctx, params)
162	    }
163	}
164	
165	/// Whether `stdin` is attached to a terminal.
166	///
167	/// Interactive prompts (`stage_review`, `$EDITOR` launch in
168	/// `stage_message`, `--step` gates) need this to fail fast in
169	/// scripted / CI contexts instead of hanging on `read_line`.
170	/// `--yes` overrides the check — script callers opt in by
171	/// asserting "all prompts auto-approved".
172	fn is_stdin_tty() -> bool {
173	    std::io::stdin().is_terminal()
174	}
175	
176	/// Entry point for the `push` subcommand.
177	///
178	/// 0.37.0-5 behavior: interactive flow with two approval gates
179	/// (review + message) plus polish flags: `--dry-run` prints what
180	/// would run without side effects, `--step` pauses between every
181	/// stage, non-tty stdin fails fast when prompts are required,
182	/// `--yes` opts out of all prompts. On any failure in stages 4-6
183	/// (the local mutation window between `commit-work` and
184	/// `bookmark-set`), both repos roll back to the `jj op` snapshot
185	/// recorded at the start of `commit-work`. After `push-work` the
186	/// remote boundary is crossed and recovery is forward-only.
187	///
188	/// `ctx` is unused today (push reads `.vc-config.toml` for its
189	/// state-file layout); it's present for the uniform
190	/// subcommand-layer signature.
191	pub fn push(_ctx: &Context, params: &PushParams) -> Result<(), Box<dyn std::error::Error>> {
192	    let cwd = std::env::current_dir()?;
193	    push_in(&cwd, params)
194	}
195	
196	/// `push` parameterized on the workspace root. CLI dispatch calls
197	/// this with `std::env::current_dir()`; integration tests call it
198	/// with a fixture tempdir so the stages mutate the fixture's repos
199	/// instead of the developer's working tree.
200	///
201	/// The stages run in a straight line. The mutation window
202	/// (`commit-work` → `bookmark-set`) is wrapped so a failure inside
203	/// it restores both repos from snapshots taken just before it;
204	/// after `push-work` the remote boundary is crossed and a failure
205	/// simply propagates.
206	pub(crate) fn push_in(
207	    workspace_root: &Path,
208	    params: &PushParams,
209	) -> Result<(), Box<dyn std::error::Error>> {
210	    if params.dry_run {
211	        info!("push: DRY-RUN — no side effects (no commits, no pushes)");
212	    }
213	
214	    let bookmark = params.bookmark.as_deref().ok_or(
215	        "push: a bookmark is required — pass it as a positional \
216	         (`vc-x1 push main`) or via `--bookmark main`",
217	    )?;
218	
219	    stage_review(workspace_root, params)?;
220	    step_gate(params, "review", "message")?;
221	
222	    let run = stage_message(workspace_root, params)?;
223	    step_gate(params, "message", "commit-work")?;
224	
225	    // Snapshot both repos before the first mutation. Dry-runs
226	    // mutate nothing, so they need no rollback target.
227	    let snapshots = if params.dry_run {
228	        None
229	    } else {
230	        Some(Snapshots {
231	            work: current_op_id(workspace_root)?,
232	            bot: current_op_id(&bot_path(workspace_root)?)?,
233	        })
234	    };
235	
236	    if let Err(e) = mutate(workspace_root, bookmark, &run, params) {
237	        if let Some(snapshots) = &snapshots {
238	            rollback_on_failure(workspace_root, snapshots, e.as_ref());
239	        }
240	        return Err(e);
241	    }
242	
243	    stage_push_work(workspace_root, bookmark, params)?;
244	
245	    if params.no_squash_push {
246	        info!("push squash-push-bot: skip (--no-squash-push)");
247	    } else {
248	        step_gate(params, "push-work", "squash-push-bot")?;
249	        stage_squash_push_bot(workspace_root, params)?;
250	    }
251	
252	    if params.dry_run {
253	        info!("push: DRY-RUN complete — no changes written");
254	        return Ok(());
255	    }
256	
257	    // Honest completion: confirm the world matches what the stages
258	    // claim to have done. Catches the 0.37.1 false-success symptom.
259	    // Warning-only — work has crossed the remote boundary by now, so
260	    // rollback isn't sound and the user needs to investigate.
261	    match verify_completion(workspace_root, bookmark, &run) {
262	        Ok(()) => info!("push: completed all stages (verified)"),
263	        Err(e) => {
264	            warn!("push: completed stages but post-completion verification failed:");
265	            warn!("  {e}");
266	            warn!("  investigate the discrepancy before the next push");
267	        }
268	    }
269	    Ok(())
270	}
271	
272	/// The rollback-eligible window: everything that mutates a repo
273	/// before anything reaches a remote.
274	fn mutate(
275	    root: &Path,
276	    bookmark: &str,
277	    run: &Run,
278	    params: &PushParams,
279	) -> Result<(), Box<dyn std::error::Error>> {
280	    stage_commit_work(root, run, params)?;
281	    step_gate(params, "commit-work", "commit-bot")?;
282	    stage_commit_bot(root, run, params)?;
283	    step_gate(params, "commit-bot", "bookmark-set")?;
284	    stage_bookmark_set(root, bookmark, params)?;
285	    step_gate(params, "bookmark-set", "push-work")?;
286	    Ok(())
287	}
288	
289	/// `--step`: pause between stages so the user can inspect the
290	/// repos before the next one runs.
291	///
292	/// Skipped entirely without `--step`, and under `--yes` or a
293	/// non-tty stdin the prompt would hang, so `--yes` bypasses it and
294	/// a non-tty without `--yes` is an error rather than a hang.
295	fn step_gate(
296	    params: &PushParams,
297	    done: &str,
298	    next: &str,
299	) -> Result<(), Box<dyn std::error::Error>> {
300	    if !params.step {
301	        return Ok(());
302	    }
303	    if params.yes {
304	        debug!("push step: --yes skips step gate between {done} and {next}");
305	        return Ok(());
306	    }
307	    if !is_stdin_tty() {
308	        return Err("push: --step requires a tty (stdin is not interactive); \
309	                    add --yes to bypass step gates in non-interactive contexts"
310	            .into());
311	    }
312	    let answer = prompt(&format!(
313	        "push step: {done} done. Continue to {next}? [y/N] "
314	    ))?;
315	    let normalized = answer.trim().to_ascii_lowercase();
316	    if normalized != "y" && normalized != "yes" {
317	        return Err(format!("push: step gate declined after {done} (got {answer:?})").into());
318	    }
319	    Ok(())
320	}
321	
322	/// Full path of the bot repo for a given workspace root, resolved
323	/// from `.vc-config.toml`'s `repos.bot` (push requires a dual
324	/// workspace). Also the dual-mode entry preflight: resolution
325	/// verifies both repos' recorded topology agrees and errors loudly
326	/// — with everything known, changing nothing — when it doesn't.
327	fn bot_path(workspace_root: &Path) -> Result<PathBuf, Box<dyn std::error::Error>> {
328	    crate::common::require_bot_dir(workspace_root)
329	}
330	
331	/// Restore both repos to their `jj op` snapshots.
332	///
333	/// Best-effort — if the restore itself fails we warn but don't
334	/// shadow the original error the caller will propagate. Exposed at
335	/// `pub(crate)` so integration tests can exercise the rollback path
336	/// directly rather than forcing a stage failure.
337	pub(crate) fn rollback_on_failure(
338	    root: &Path,
339	    snapshots: &Snapshots,
340	    original: &dyn std::error::Error,
341	) {
342	    warn!("push: rolling back both repos after: {original}");
343	    match op_restore(root, &snapshots.work) {
344	        Ok(()) => info!("push: restored work repo to op {}", snapshots.work),
345	        Err(e) => warn!("push: work repo restore failed: {e}"),
346	    }
347	    // Rollback is best-effort inside an error path — a failed
348	    // bot-dir resolution is reported, not propagated.
349	    match bot_path(root) {
350	        Ok(bot) => match op_restore(&bot, &snapshots.bot) {
351	            Ok(()) => info!("push: restored bot repo to op {}", snapshots.bot),
352	            Err(e) => warn!("push: bot repo restore failed: {e}"),
353	        },
354	        Err(e) => warn!("push: bot repo restore skipped (unresolvable): {e}"),
355	    }
356	}
357	
358	/// Review: first approval gate — "is the work done right?".
359	///
360	/// Shows a `jj diff --stat` of the pending changes in both repos
361	/// and prompts the user to continue. `--yes` short-circuits the
362	/// prompt (required for scripted / non-tty use). In `--dry-run`
363	/// the diff is still shown (that's the point of dry-run — see
364	/// what *would* be reviewed) but approval is auto-granted.
365	fn stage_review(root: &Path, params: &PushParams) -> Result<(), Box<dyn std::error::Error>> {
366	    let bot = bot_path(root)?;
367	    let work_arg = root.to_string_lossy();
368	    let bot_arg = bot.to_string_lossy();
369	    info!("push review: pending changes:");
370	    info!("  work ({work_arg}):");
371	    let work_stat = run("jj", &["diff", "--stat", "-R", &work_arg], root)?;
372	    for line in work_stat.lines() {
373	        info!("    {line}");
374	    }
375	    info!("  .claude ({bot_arg}):");
376	    let bot_stat = run("jj", &["diff", "--stat", "-R", &bot_arg], root)?;
377	    for line in bot_stat.lines() {
378	        info!("    {line}");
379	    }
380	    if params.yes {
381	        info!("push review: auto-approved (--yes)");
382	        return Ok(());
383	    }
384	    if params.dry_run {
385	        info!("push review: [dry-run] auto-approved");
386	        return Ok(());
387	    }
388	    if !is_stdin_tty() {
389	        return Err("push review: stdin is not a tty; \
390	                    pass --yes to auto-approve in non-interactive contexts"
391	            .into());
392	    }
393	    let answer = prompt("push review: approve and continue to message stage? [y/N] ")?;
394	    let normalized = answer.trim().to_ascii_lowercase();
395	    if normalized == "y" || normalized == "yes" {
396	        Ok(())
397	    } else {
398	        Err(format!(
399	            "push review: declined (got {answer:?}); re-run with --yes or confirm with 'y'"
400	        )
401	        .into())
402	    }
403	}
404	
405	/// Message: resolve the commit message and capture both repos'
406	/// pre-commit changeIDs, so each side's `ochid:` trailer can name
407	/// the other.
408	///
409	/// Title/body come from `--title`/`--body`, else `$EDITOR`. There
410	/// is no persisted message to fall back on: a rerun supplies the
411	/// flags again or opens the editor again, which is the cost of
412	/// having no state file and a cheap one — the message is in the
413	/// user's scrollback either way.
414	///
415	/// When neither repo has pending changes, no commit will be made on
416	/// either side, so an absent message is not an error — the run is
417	/// publish-only (bookmark + remote), which is the trapezoid
418	/// recipe's final step.
419	fn stage_message(root: &Path, params: &PushParams) -> Result<Run, Box<dyn std::error::Error>> {
420	    let bot = bot_path(root)?;
421	    // Both sides resolve their chid the same way: `@` when the
422	    // working copy has changes (it becomes `@-` once committed),
423	    // else the existing `@-` (which stays put, because that side's
424	    // commit stage skips). Taking `@` unconditionally on the work
425	    // side is what minted an empty stamped duplicate in bugs.md #4.
426	    let work_had_changes = !jj::is_empty(root, "@")?;
427	    let work_ref = if work_had_changes { "@" } else { "@-" };
428	    let work_chid = jj::chid_of(root, work_ref)?;
429	    let bot_had_changes = !jj::is_empty(&bot, "@")?;
430	    let bot_ref = if bot_had_changes { "@" } else { "@-" };
431	    let bot_chid = jj::chid_of(&bot, bot_ref)?;
432	    let will_commit = work_had_changes || bot_had_changes;
433	
434	    let (title, body) = match (params.title.clone(), params.body.clone()) {
435	        (Some(t), Some(b)) => (t, b),
436	        _ if !will_commit => {
437	            info!("push message: skip (neither repo has pending changes)");
438	            (String::new(), String::new())
439	        }
440	        _ => {
441	            if params.yes {
442	                return Err("push message: --yes given but --title/--body missing \
443	                            — pass both flags or run interactively."
444	                    .into());
445	            }
446	            if params.dry_run {
447	                return Err("push message: --dry-run given but --title/--body missing \
448	                            — pass both flags so dry-run has a message to preview."
449	                    .into());
450	            }
451	            if !is_stdin_tty() {
452	                return Err("push message: stdin is not a tty and no --title/--body \
453	                            supplied; cannot launch $EDITOR in a non-interactive \
454	                            context. Pass --title and --body, or run interactively."
455	                    .into());
456	            }
457	            compose_message_via_editor()?
458	        }
459	    };
460	
461	    info!(
462	        "push message: title=\"{}\", work_chid={work_chid}, bot_chid={bot_chid}, work_had_changes={work_had_changes}, bot_had_changes={bot_had_changes}",
463	        title.lines().next().unwrap_or("") // OK: obvious
464	    );
465	    Ok(Run {
466	        title,
467	        body,
468	        work_chid,
469	        bot_chid,
470	        bot_had_changes,
471	    })
472	}
473	
474	/// Launch `$EDITOR` (falling back to `vi`) on a scratch template,
475	/// then parse the saved content into a `(title, body)` tuple. Lines
476	/// starting with `#` are treated as comments and stripped. Empty
477	/// input aborts the push.
478	///
479	/// The template lives in the system temp dir, keyed by pid: with no
480	/// state dir left to put it in, and the file being read back within
481	/// the same call, it never needs to outlive the process.
482	fn compose_message_via_editor() -> Result<(String, String), Box<dyn std::error::Error>> {
483	    let editor = std::env::var("EDITOR")
484	        .or_else(|_| std::env::var("VISUAL"))
485	        .unwrap_or_else(|_| "vi".to_string()); // OK: POSIX fallback when nothing is configured
486	    let msg_path =
487	        std::env::temp_dir().join(format!("vc-x1-push-message-{}.txt", std::process::id()));
488	    let template = "\
489	# Leave as-is to abort. Enter the Title on the first line,
490	# optionally followed by the Body on subsequent lines. The
491	# blank line between Title and Body is inserted automatically,
492	# and the ochid trailer is appended per-repo automatically —
493	# don't add either here.
494	# Lines starting with `#` are ignored.
495	";
496	    fs::write(&msg_path, template)?;
497	    info!("push message: launching {editor} on {}", msg_path.display());
498	    let status = std::process::Command::new(&editor)
499	        .arg(&msg_path)
500	        .status()
501	        .map_err(|e| format!("failed to launch {editor}: {e}"))?;
502	    if !status.success() {
503	        return Err(format!("{editor} exited non-zero ({status})").into());
504	    }
505	    let content = fs::read_to_string(&msg_path)?;
506	    let _ = fs::remove_file(&msg_path);
507	    parse_message(&content)
508	        .ok_or_else(|| "push message: template was left empty or all-comments — aborting".into())
509	}
510	
511	/// Parse the editor-saved message into `(title, body)`. Strips
512	/// `#`-prefixed comment lines, trims surrounding blanks, and treats
513	/// the first non-comment line as the title with everything after as
514	/// the body (a blank line between is allowed but not required —
515	/// the commit stages insert the title/body separator themselves).
516	/// Returns `None` when the message has no non-comment content.
517	fn parse_message(raw: &str) -> Option<(String, String)> {
518	    let mut meaningful = String::new();
519	    for line in raw.lines() {
520	        let trimmed_left = line.trim_start();
521	        if trimmed_left.starts_with('#') {
522	            continue;
523	        }
524	        meaningful.push_str(line);
525	        meaningful.push('\n');
526	    }
527	    let trimmed = meaningful.trim();
528	    if trimmed.is_empty() {
529	        return None;
530	    }
531	    let mut lines = trimmed.lines();
532	    let title = lines.next().unwrap_or("").trim().to_string(); // OK: trimmed non-empty ⇒ first line exists
533	    let body = lines.collect::<Vec<_>>().join("\n").trim().to_string();
534	    if title.is_empty() {
535	        return None;
536	    }
537	    Some((title, body))
538	}
539	
540	/// Commit work repo with `title` / `body` and the `ochid:` trailer
541	/// pointing at `.claude`'s chid, or skip when the working copy has
542	/// nothing pending — the same rule `stage_commit_bot` follows.
543	///
544	/// Skipping matters in two situations:
545	///
546	/// - The rung was committed by hand before invoking push. Committing
547	///   the empty `@` anyway minted a stamped empty duplicate on top of
548	///   the real commit (bugs.md #4).
549	/// - A publish-only run, where the commits already exist and only
550	///   the bookmark and the remote still need advancing — the
551	///   trapezoid recipe's final step.
552	///
553	/// In both cases the existing top commit is published as-is; push
554	/// does not rewrite a description it didn't author.
555	fn stage_commit_work(
556	    root: &Path,
557	    run_msg: &Run,
558	    params: &PushParams,
559	) -> Result<(), Box<dyn std::error::Error>> {
560	    if jj::is_empty(root, "@")? {
561	        warn!(
562	            "push commit-work: skip (work repo had no pending changes); \
563	             the supplied message is not applied — the existing top \
564	             commit is published as-is"
565	        );
566	        return Ok(());
567	    }
568	    let (title, body) = (&run_msg.title, &run_msg.body);
569	    let bot_prefix = crate::desc_helpers::ochid_prefix_for(&bot_path(root)?)?;
570	    let body_with_trailer = format!("{body}\n\nochid: {bot_prefix}{}", run_msg.bot_chid);
571	    let work_arg = root.to_string_lossy();
572	    if params.dry_run {
573	        info!(
574	            "push commit-work: [dry-run] would run jj commit -R {work_arg} -m \"{title}\" -m <body+ochid>"
575	        );
576	        return Ok(());
577	    }
578	    info!("push commit-work: commit -R {work_arg}");
579	    jj::commit(root, &format!("{title}\n\n{body_with_trailer}"))?;
580	    Ok(())
581	}
582	
583	/// Commit `.claude` with the same title/body and the ochid trailer
584	/// pointing at the work commit's chid, or skip if `.claude` had no
585	/// pending changes.
586	fn stage_commit_bot(
587	    root: &Path,
588	    run_msg: &Run,
589	    params: &PushParams,
590	) -> Result<(), Box<dyn std::error::Error>> {
591	    if !run_msg.bot_had_changes {
592	        info!("push commit-bot: skip (.claude had no pending changes)");
593	        return Ok(());
594	    }
595	    let (title, body) = (&run_msg.title, &run_msg.body);
596	    let body_with_trailer = format!("{body}\n\nochid: /{}", run_msg.work_chid);
597	    let bot = bot_path(root)?;
598	    let bot_arg = bot.to_string_lossy();
599	    if params.dry_run {
600	        info!(
601	            "push commit-bot: [dry-run] would run jj commit -R {bot_arg} -m \"{title}\" -m <body+ochid>"
602	        );
603	        return Ok(());
604	    }
605	    info!("push commit-bot: commit -R {bot_arg}");
606	    jj::commit(&bot, &format!("{title}\n\n{body_with_trailer}"))?;
607	    Ok(())
608	}
609	
610	/// Advance each repo's bookmark to its `@-`: the work repo advances
611	/// `state.bookmark`, the bot repo always advances
612	/// `BOT_BOOKMARK` (`main`) — a feature bookmark must never be
613	/// created in the linear-journal bot repo.
614	fn stage_bookmark_set(
615	    root: &Path,
616	    bookmark: &str,
617	    params: &PushParams,
618	) -> Result<(), Box<dyn std::error::Error>> {
619	    let bk = bookmark;
620	    let work_arg = root.to_string_lossy();
621	    let bot = bot_path(root)?;
622	    let bot_arg = bot.to_string_lossy();
623	    if params.dry_run {
624	        info!(
625	            "push bookmark-set: [dry-run] would run jj bookmark set {bk} -r @- -R {work_arg} / {BOT_BOOKMARK} -r @- -R {bot_arg}"
626	        );
627	        return Ok(());
628	    }
629	    info!(
630	        "push bookmark-set: bookmark set {bk} -r @- -R {work_arg} / {BOT_BOOKMARK} -r @- -R {bot_arg}"
631	    );
632	    jj::bookmark_set(root, bk, "@-")?;
633	    jj::bookmark_set(&bot, BOT_BOOKMARK, "@-")?;
634	    Ok(())
635	}
636	
637	/// Push the work repo's bookmark to origin.
638	///
639	/// Checks its own precondition — every remote ref for the bookmark
640	/// is tracked — which is where preflight's tracking check moved
641	/// when preflight was retired. A never-pushed bookmark has no
642	/// remote ref and passes; the check catches a ref that exists but
643	/// isn't tracked, which would otherwise push into a ref jj won't
644	/// follow afterwards.
645	///
646	/// Rerunning is safe without a guard of its own: `jj git push` on
647	/// an already-published bookmark reports nothing to do.
648	fn stage_push_work(
649	    root: &Path,
650	    bookmark: &str,
651	    params: &PushParams,
652	) -> Result<(), Box<dyn std::error::Error>> {
653	    let bk = bookmark;
654	    let work_arg = root.to_string_lossy();
655	    if params.dry_run {
656	        info!("push push-work: [dry-run] would run jj git push --bookmark {bk} -R {work_arg}");
657	        return Ok(());
658	    }
659	    crate::common::verify_tracking(root, bk)?;
660	    info!("push push-work: git push --bookmark {bk} -R {work_arg}");
661	    jj::git_push_bookmark(root, bk)?;
662	    Ok(())
663	}
664	
665	/// Squash-push `.claude` in-process, always pushing
666	/// `BOT_BOOKMARK` (`main`) — the bot repo's bookmark is
667	/// pinned, so the work-repo bookmark plays no part here.
668	///
669	/// - Squashes the tail (session writes that landed since
670	///   `commit-bot`) into the bot commit, then pushes — via
671	///   `squash_push::squash_push`, so the ochid-drop guard
672	///   applies and a failure is a visible push failure.
673	/// - In-process since 0.69.0-1 (the stage's detached child died
674	///   silently at sandbox teardown — the loss diagnosed in
675	///   0.68.1).
676	/// - `--no-squash-push` turns this stage into a no-op so the
677	///   squash+push can be run manually.
678	fn stage_squash_push_bot(
679	    root: &Path,
680	    params: &PushParams,
681	) -> Result<(), Box<dyn std::error::Error>> {
682	    let bk = BOT_BOOKMARK;
683	    let bot = bot_path(root)?;
684	    let bot_arg = bot.to_string_lossy();
685	    if params.dry_run {
686	        info!(
687	            "push squash-push-bot: [dry-run] would squash @ → @- and push {bk} in {bot_arg} (in-process)"
688	        );
689	        return Ok(());
690	    }
691	    info!("push squash-push-bot: squash @ → @- + push {bk} -R {bot_arg} (in-process)");
692	    let sp = crate::squash_push::SquashPushParams {
693	        repo: bot.clone(),
694	        squash: SquashSpec {
695	            source: "@".to_string(),
696	            target: "@-".to_string(),
697	        },
698	        bookmark: bk.to_string(),
699	        // Mid-push the mismatch is the normal state (bookmark-set
700	        // just moved main; this stage publishes it) — don't report
701	        // a lost publish.
702	        report_publish_state: false,
703	    };
704	    crate::squash_push::squash_push(&sp)
705	}
706	
707	/// Verify the world matches what the stages claim to have done.
708	///
709	/// Runs after the last stage and confirms the post-conditions are
710	/// real — directly addresses the 0.37.1 false-success symptom (push
711	/// declared "completed all stages" while the working copy still held
712	/// uncommitted changes).
713	///
714	/// Three checks:
715	///
716	/// 1. Work's bookmark is at a commit whose chid matches the run's
717	///    `work_chid`.
718	/// 2. Work's working copy has no uncommitted changes (commit-work
719	///    should have captured anything that was there).
720	/// 3. `.claude`'s bookmark is at the run's `bot_chid`.
721	///    `.claude`'s working copy (`@`) may legitimately have new
722	///    session writes that landed after squash-push-bot's squash —
723	///    the tail rides into the next cycle's commit — so no
724	///    working-copy-clean check on `.claude`.
725	///
726	/// On any mismatch: returns `Err`. The caller surfaces it as a loud
727	/// warning rather than blocking — push has already crossed the
728	/// remote boundary, work is live on origin, and the warning prompts
729	/// the user to investigate.
730	fn verify_completion(
731	    root: &Path,
732	    bookmark: &str,
733	    run_msg: &Run,
734	) -> Result<(), Box<dyn std::error::Error>> {
735	    let root_str = root.to_string_lossy();
736	    let cwd = Path::new(".");
737	
738	    // 1. work bookmark at the run's work_chid.
739	    let actual = jj::chid_of(root, bookmark)?;
740	    if actual != run_msg.work_chid {
741	        return Err(format!(
742	            "completion sanity: work bookmark '{bookmark}' is at chid '{actual}' but \
743	             this run committed '{}'.",
744	            run_msg.work_chid
745	        )
746	        .into());
747	    }
748	
749	    // 2. work working copy (`@`) clean (no uncommitted changes). Use the `empty`
750	    // template — `jj diff --stat` always emits a "0 files changed"
751	    // line even when clean, so plain output-emptiness check would
752	    // false-positive.
753	    if !jj::is_empty(root, "@")? {
754	        let wc_diff = run("jj", &["diff", "--stat", "-r", "@", "-R", &root_str], cwd)?;
755	        return Err(format!(
756	            "completion sanity: work working copy has uncommitted changes (push completed \
757	             but working copy dirty?). Diff stat:\n{wc_diff}"
758	        )
759	        .into());
760	    }
761	
762	    // 3. .claude's pinned bookmark (main) at the run's bot_chid.
763	    let actual = jj::chid_of(&bot_path(root)?, BOT_BOOKMARK)?;
764	    if actual != run_msg.bot_chid {
765	        return Err(format!(
766	            "completion sanity: .claude bookmark '{BOT_BOOKMARK}' is at chid \
767	             '{actual}' but this run committed '{}'.",
768	            run_msg.bot_chid
769	        )
770	        .into());
771	    }
772	
773	    Ok(())
774	}
775	
776	#[cfg(test)]
777	mod tests;
778	
779	#[cfg(test)]
780	mod integration_tests;
781

