1	//! The `squash-push` subcommand: squash the working copy into its
2	//! parent, advance a bookmark, and push — capture a repo's trailing
3	//! writes and publish them in one step.
4	//!
5	//! - Built for the bot's `.claude` bot repo, whose working copy
6	//!   accumulates session data continuously (the session tail); also
7	//!   useful on the work repo as a deliberate amend-and-push (a
8	//!   published-history rewrite, so the push is a forced update).
9	//! - Runs fully in-process: preflight validations, then squash +
10	//!   bookmark-set + push. A failure is a visible non-zero exit
11	//!   (the retired 0.69.0-2 predecessor delegated to a detached
12	//!   child that a sandboxed run silently killed — the loss
13	//!   diagnosed in 0.68.1).
14	//! - Reports an at-rest publish mismatch (BOOKMARK not matching
15	//!   `BOOKMARK@origin` — an earlier publish was lost) and proceeds:
16	//!   publishing is the command's job, so healing is not
17	//!   auto-fixing. Suppressed when run as push's `squash-push-bot`
18	//!   stage, where the mismatch is the normal mid-push state.
19	
20	use std::path::{Path, PathBuf};
21	
22	use clap::Args;
23	use log::{debug, info, warn};
24	
25	use crate::common::run;
26	use crate::context::Context;
27	use crate::desc_helpers::extract_ochids;
28	use crate::jj;
29	use crate::options_flags::squash::{SquashOption, SquashSpec};
30	use crate::subcommand::SubcommandRunner;
31	
32	/// Squash `@` into `@-`, advance BOOKMARK, and push.
33	///
34	/// Captures a repo's trailing working-copy writes into the last
35	/// commit and publishes it — rewriting an already-pushed commit is
36	/// a forced update. Zero-ceremony default: bare `vc-x1 squash-push`
37	/// squashes `@ → @-` and pushes `main` in `.`.
38	#[derive(Args, Debug)]
39	pub struct SquashPushArgs {
40	    /// Bookmark to advance and push
41	    #[arg(value_name = "BOOKMARK", default_value = "main")]
42	    pub bookmark: String,
43	
44	    /// Path to jj repo
45	    #[arg(short = 'R', long, default_value = ".")]
46	    pub repo: PathBuf,
47	
48	    #[command(flatten)]
49	    pub squash: SquashOption,
50	}
51	
52	/// Per-invocation squash-push inputs — the clap-free shape the op
53	/// works against. Built from `SquashPushArgs` at the binary edge
54	/// via `TryFrom` (fallible only on repo-path canonicalization);
55	/// `vc-x1 push`'s `squash-push-bot` stage constructs it
56	/// directly.
57	#[derive(Debug)]
58	pub struct SquashPushParams {
59	    pub repo: PathBuf,
60	    pub squash: SquashSpec,
61	    pub bookmark: String,
62	    /// Report an at-rest publish mismatch (BOOKMARK not matching
63	    /// `BOOKMARK@origin` — an earlier publish was lost) before
64	    /// proceeding. True for CLI invocations, which run at rest;
65	    /// `vc-x1 push`'s `squash-push-bot` stage sets false — there
66	    /// the mismatch is the normal mid-push state (`bookmark-set`
67	    /// just moved the bookmark, this stage publishes it), so the
68	    /// report would be a false alarm.
69	    pub report_publish_state: bool,
70	}
71	
72	impl TryFrom<&SquashPushArgs> for SquashPushParams {
73	    type Error = String;
74	
75	    /// Canonicalize `--repo` (early, visible failure on a bad path)
76	    /// and fill the `--squash` default; BOOKMARK maps straight over.
77	    fn try_from(a: &SquashPushArgs) -> Result<Self, String> {
78	        let repo = std::fs::canonicalize(&a.repo)
79	            .map_err(|e| format!("cannot resolve repo path '{}': {e}", a.repo.display()))?;
80	        Ok(SquashPushParams {
81	            repo,
82	            squash: a.squash.value.clone().unwrap_or_else(|| SquashSpec {
83	                source: "@".to_string(),
84	                target: "@-".to_string(),
85	            }), // OK: --squash absent → the command's default @,@- pair
86	            bookmark: a.bookmark.clone(),
87	            report_publish_state: true,
88	        })
89	    }
90	}
91	
92	impl SubcommandRunner for SquashPushArgs {
93	    type Params = SquashPushParams;
94	
95	    /// Delegate to the `TryFrom<&SquashPushArgs>` impl above.
96	    fn to_params(&self) -> Result<Self::Params, String> {
97	        SquashPushParams::try_from(self)
98	    }
99	
100	    /// Run the `squash-push` op (`ctx` unused — the op is fully
101	    /// parameterized by `Params`).
102	    fn run(_ctx: &Context, params: &Self::Params) -> Result<(), Box<dyn std::error::Error>> {
103	        squash_push(params)
104	    }
105	}
106	
107	/// Validate inputs before mutating anything.
108	///
109	/// Catches the common failure modes up front — unresolvable
110	/// revsets, an ochid-dropping squash, conflicts, a missing /
111	/// untracked / non-forward bookmark, an undescribed push target —
112	/// so the run fails before the squash rewrites history.
113	fn preflight(params: &SquashPushParams) -> Result<(), Box<dyn std::error::Error>> {
114	    debug!("preflight: checking params");
115	    let repo = &params.repo;
116	    let repo_str = params.repo.to_string_lossy();
117	    let sq = &params.squash;
118	    let bookmark = &params.bookmark;
119	
120	    // Verify squash revsets resolve to something, and that the squash
121	    // won't drop source-only ochid: trailers.
122	    if !jj::rev_exists(repo, &sq.source)? {
123	        return Err(format!("squash source '{}' does not resolve", sq.source).into());
124	    }
125	    if !jj::rev_exists(repo, &sq.target)? {
126	        return Err(format!("squash target '{}' does not resolve", sq.target).into());
127	    }
128	    check_squash_keeps_ochids(repo, sq)?;
129	
130	    // Refuse to operate on a repo with conflicts.
131	    if jj::matches(repo, "conflicts()")? {
132	        return Err(format!("repo '{repo_str}' has conflicts — resolve before squash-push").into());
133	    }
134	
135	    // Bookmark: existence, tracking, forward-only move, push-target description.
136	    if jj::bookmark_list(repo, bookmark)?.is_empty() {
137	        return Err(format!("bookmark '{bookmark}' does not exist").into());
138	    }
139	
140	    crate::common::verify_tracking(&params.repo, bookmark)?;
141	
142	    if !jj::matches(repo, &format!("{bookmark}::({})", sq.target))? {
143	        return Err(format!(
144	            "bookmark '{bookmark}' move is not forward — current position is not an \
145	             ancestor of '{}' (would diverge)",
146	            sq.target
147	        )
148	        .into());
149	    }
150	
151	    if jj::desc_of(repo, &sq.target)?.is_empty() {
152	        return Err(format!(
153	            "push target '{}' has no description — push would fail \
154	             (run `jj describe -r {} -R {repo_str}` first)",
155	            sq.target, sq.target
156	        )
157	        .into());
158	    }
159	
160	    Ok(())
161	}
162	
163	/// Return the `ochid:` trailer values present in `source_desc` but
164	/// absent from `target_desc` — the trailers a squash with
165	/// `--use-destination-message` would silently drop (the ochid-loss incident recorded in 0.65.1).
166	fn ochids_at_risk(source_desc: &str, target_desc: &str) -> Vec<String> {
167	    let kept = extract_ochids(target_desc);
168	    extract_ochids(source_desc)
169	        .into_iter()
170	        .filter(|ochid| !kept.contains(ochid))
171	        .collect()
172	}
173	
174	/// Refuse a squash that would drop the source message's `ochid:`
175	/// trailers.
176	///
177	/// - Compares the two messages' `ochid:` trailers; errors when the
178	///   source carries any the destination's message lacks —
179	///   `--use-destination-message` would discard them, leaving the
180	///   counterpart repo's cross-links dangling (recorded 0.65.1, guarded since 0.65.2).
181	fn check_squash_keeps_ochids(
182	    repo: &Path,
183	    sq: &SquashSpec,
184	) -> Result<(), Box<dyn std::error::Error>> {
185	    let at_risk = ochids_at_risk(
186	        &jj::desc_of(repo, &sq.source)?,
187	        &jj::desc_of(repo, &sq.target)?,
188	    );
189	    if at_risk.is_empty() {
190	        return Ok(());
191	    }
192	    let listed = at_risk
193	        .iter()
194	        .map(|ochid| format!("  {ochid}"))
195	        .collect::<Vec<_>>()
196	        .join("\n");
197	    Err(format!(
198	        "refusing squash {} → {}: the squash would drop ochid: trailers\n\
199	         the destination's message lacks:\n\
200	         {listed}\n\
201	         merge the messages by hand (`jj describe {} -R {}`) or clear\n\
202	         the source's description, then retry",
203	        sq.source,
204	        sq.target,
205	        sq.target,
206	        repo.display(),
207	    )
208	    .into())
209	}
210	
211	/// True when `rev` has no file changes and no description — nothing
212	/// worth squashing.
213	fn rev_is_empty_undescribed(repo: &Path, rev: &str) -> Result<bool, Box<dyn std::error::Error>> {
214	    if !jj::is_empty(repo, rev)? {
215	        return Ok(false);
216	    }
217	    Ok(jj::desc_of(repo, rev)?.is_empty())
218	}
219	
220	/// Run the `squash-push` op: preflight, then squash (skipped when
221	/// the source is empty and undescribed) + bookmark-set + push.
222	///
223	/// - With an empty source and the bookmark already matching both
224	///   the squash target and the remote, reports "already sync'd"
225	///   and exits 0 — nothing to do.
226	/// - With an empty source but the remote behind, skips the squash
227	///   and still pushes.
228	pub fn squash_push(params: &SquashPushParams) -> Result<(), Box<dyn std::error::Error>> {
229	    debug!("squash_push: entry params={params:?}");
230	    let repo_str = params.repo.to_string_lossy().to_string();
231	    let cwd = std::path::Path::new(".");
232	    let sq = &params.squash;
233	    let bookmark = &params.bookmark;
234	
235	    preflight(params)?;
236	
237	    // Report an at-rest publish mismatch before touching anything
238	    // (0.69.0-3): the bookmark should match its origin counterpart
239	    // between runs, so a mismatch means an earlier publish was
240	    // lost. Publishing is this command's job, so it proceeds — the
241	    // report is the point, not a refusal. Suppressed when run as
242	    // push's `squash-push-bot` stage (see `report_publish_state`).
243	    if params.report_publish_state {
244	        match crate::common::bookmark_publish_state(&params.repo, bookmark)? {
245	            crate::common::PublishState::InSync => {}
246	            crate::common::PublishState::NeverPushed => info!(
247	                "squash-push: '{bookmark}' has never been pushed to origin — this run will publish it"
248	            ),
249	            crate::common::PublishState::Mismatch { local, remote } => warn!(
250	                "squash-push: '{bookmark}' ({}) does not match '{bookmark}@origin' ({}) — an \
251	                 earlier publish was likely lost; this run will publish it",
252	                &local[..local.len().min(12)],
253	                &remote[..remote.len().min(12)]
254	            ),
255	        }
256	    }
257	
258	    // Empty-source handling: nothing to squash. If the bookmark
259	    // already matches both the target and the remote, nothing to
260	    // push either — report and exit 0.
261	    if rev_is_empty_undescribed(&params.repo, &sq.source)? {
262	        let target_cid = jj::cid_of(&params.repo, &sq.target)?;
263	        let bookmark_cid = jj::cid_of(&params.repo, bookmark)?;
264	        let remote_cid =
265	            jj::cid_of(&params.repo, &format!("{bookmark}@origin")).unwrap_or_default(); // OK: unresolvable remote bookmark (never pushed) → treated as not sync'd
266	        if bookmark_cid == target_cid && bookmark_cid == remote_cid {
267	            info!("squash-push: repo '{repo_str}' is already sync'd with remote");
268	            return Ok(());
269	        }
270	        info!(
271	            "squash-push: {} is empty — skipping squash, still pushing",
272	            sq.source
273	        );
274	    } else {
275	        info!("squash-push: squashing {} → {}...", sq.source, sq.target);
276	        run(
277	            "jj",
278	            &[
279	                "squash",
280	                "--ignore-immutable",
281	                "--use-destination-message",
282	                "--from",
283	                &sq.source,
284	                "--into",
285	                &sq.target,
286	                "-R",
287	                &repo_str,
288	            ],
289	            cwd,
290	        )?;
291	    }
292	
293	    info!(
294	        "squash-push: setting bookmark '{bookmark}' to {}...",
295	        sq.target
296	    );
297	    jj::bookmark_set(&params.repo, bookmark, &sq.target)?;
298	
299	    info!("squash-push: pushing '{bookmark}' to origin...");
300	    jj::git_push_bookmark(&params.repo, bookmark)?;
301	
302	    info!("squash-push: done");
303	    Ok(())
304	}
