//! The `squash-push` subcommand: squash the working copy into its
//! parent, advance a bookmark, and push — capture a repo's trailing
//! writes and publish them in one step.
//!
//! - Built for the bot's `.claude` bot repo, whose working copy
//!   accumulates session data continuously (the session tail); also
//!   useful on the work repo as a deliberate amend-and-push (a
//!   published-history rewrite, so the push is a forced update).
//! - Runs fully in-process: preflight validations, then squash +
//!   bookmark-set + push. A failure is a visible non-zero exit
//!   (the retired 0.69.0-2 predecessor delegated to a detached
//!   child that a sandboxed run silently killed — the loss
//!   diagnosed in 0.68.1).
//! - Reports an at-rest publish mismatch (BOOKMARK not matching
//!   `BOOKMARK@origin` — an earlier publish was lost) and proceeds:
//!   publishing is the command's job, so healing is not
//!   auto-fixing. Suppressed when run as push's `squash-push-bot`
//!   stage, where the mismatch is the normal mid-push state.

use std::path::{Path, PathBuf};

use clap::Args;
use log::{debug, info, warn};

use crate::common::run;
use crate::context::Context;
use crate::desc_helpers::extract_ochids;
use crate::jj;
use crate::options_flags::squash::{SquashOption, SquashSpec};
use crate::subcommand::SubcommandRunner;

/// Squash `@` into `@-`, advance BOOKMARK, and push.
///
/// Captures a repo's trailing working-copy writes into the last
/// commit and publishes it — rewriting an already-pushed commit is
/// a forced update. Zero-ceremony default: bare `vc-x1 squash-push`
/// squashes `@ → @-` and pushes `main` in `.`.
#[derive(Args, Debug)]
pub struct SquashPushArgs {
    /// Bookmark to advance and push
    #[arg(value_name = "BOOKMARK", default_value = "main")]
    pub bookmark: String,

    /// Path to jj repo
    #[arg(short = 'R', long, default_value = ".")]
    pub repo: PathBuf,

    #[command(flatten)]
    pub squash: SquashOption,
}

/// Per-invocation squash-push inputs — the clap-free shape the op
/// works against. Built from `SquashPushArgs` at the binary edge
/// via `TryFrom` (fallible only on repo-path canonicalization);
/// `vc-x1 push`'s `squash-push-bot` stage constructs it
/// directly.
#[derive(Debug)]
pub struct SquashPushParams {
    pub repo: PathBuf,
    pub squash: SquashSpec,
    pub bookmark: String,
    /// Report an at-rest publish mismatch (BOOKMARK not matching
    /// `BOOKMARK@origin` — an earlier publish was lost) before
    /// proceeding. True for CLI invocations, which run at rest;
    /// `vc-x1 push`'s `squash-push-bot` stage sets false — there
    /// the mismatch is the normal mid-push state (`bookmark-set`
    /// just moved the bookmark, this stage publishes it), so the
    /// report would be a false alarm.
    pub report_publish_state: bool,
}

impl TryFrom<&SquashPushArgs> for SquashPushParams {
    type Error = String;

    /// Canonicalize `--repo` (early, visible failure on a bad path)
    /// and fill the `--squash` default; BOOKMARK maps straight over.
    fn try_from(a: &SquashPushArgs) -> Result<Self, String> {
        let repo = std::fs::canonicalize(&a.repo)
            .map_err(|e| format!("cannot resolve repo path '{}': {e}", a.repo.display()))?;
        Ok(SquashPushParams {
            repo,
            squash: a.squash.value.clone().unwrap_or_else(|| SquashSpec {
                source: "@".to_string(),
                target: "@-".to_string(),
            }), // OK: --squash absent → the command's default @,@- pair
            bookmark: a.bookmark.clone(),
            report_publish_state: true,
        })
    }
}

impl SubcommandRunner for SquashPushArgs {
    type Params = SquashPushParams;

    /// Delegate to the `TryFrom<&SquashPushArgs>` impl above.
    fn to_params(&self) -> Result<Self::Params, String> {
        SquashPushParams::try_from(self)
    }

    /// Run the `squash-push` op (`ctx` unused — the op is fully
    /// parameterized by `Params`).
    fn run(_ctx: &Context, params: &Self::Params) -> Result<(), Box<dyn std::error::Error>> {
        squash_push(params)
    }
}

/// Validate inputs before mutating anything.
///
/// Catches the common failure modes up front — unresolvable
/// revsets, an ochid-dropping squash, conflicts, a missing /
/// untracked / non-forward bookmark, an undescribed push target —
/// so the run fails before the squash rewrites history.
fn preflight(params: &SquashPushParams) -> Result<(), Box<dyn std::error::Error>> {
    debug!("preflight: checking params");
    let repo = &params.repo;
    let repo_str = params.repo.to_string_lossy();
    let sq = &params.squash;
    let bookmark = &params.bookmark;

    // Verify squash revsets resolve to something, and that the squash
    // won't drop source-only ochid: trailers.
    if !jj::rev_exists(repo, &sq.source)? {
        return Err(format!("squash source '{}' does not resolve", sq.source).into());
    }
    if !jj::rev_exists(repo, &sq.target)? {
        return Err(format!("squash target '{}' does not resolve", sq.target).into());
    }
    check_squash_keeps_ochids(repo, sq)?;

    // Refuse to operate on a repo with conflicts.
    if jj::matches(repo, "conflicts()")? {
        return Err(format!("repo '{repo_str}' has conflicts — resolve before squash-push").into());
    }

    // Bookmark: existence, tracking, forward-only move, push-target description.
    if jj::bookmark_list(repo, bookmark)?.is_empty() {
        return Err(format!("bookmark '{bookmark}' does not exist").into());
    }

    crate::common::verify_tracking(&params.repo, bookmark)?;

    if !jj::matches(repo, &format!("{bookmark}::({})", sq.target))? {
        return Err(format!(
            "bookmark '{bookmark}' move is not forward — current position is not an \
             ancestor of '{}' (would diverge)",
            sq.target
        )
        .into());
    }

    if jj::desc_of(repo, &sq.target)?.is_empty() {
        return Err(format!(
            "push target '{}' has no description — push would fail \
             (run `jj describe -r {} -R {repo_str}` first)",
            sq.target, sq.target
        )
        .into());
    }

    Ok(())
}

/// Return the `ochid:` trailer values present in `source_desc` but
/// absent from `target_desc` — the trailers a squash with
/// `--use-destination-message` would silently drop (the ochid-loss incident recorded in 0.65.1).
fn ochids_at_risk(source_desc: &str, target_desc: &str) -> Vec<String> {
    let kept = extract_ochids(target_desc);
    extract_ochids(source_desc)
        .into_iter()
        .filter(|ochid| !kept.contains(ochid))
        .collect()
}

/// Refuse a squash that would drop the source message's `ochid:`
/// trailers.
///
/// - Compares the two messages' `ochid:` trailers; errors when the
///   source carries any the destination's message lacks —
///   `--use-destination-message` would discard them, leaving the
///   counterpart repo's cross-links dangling (recorded 0.65.1, guarded since 0.65.2).
fn check_squash_keeps_ochids(
    repo: &Path,
    sq: &SquashSpec,
) -> Result<(), Box<dyn std::error::Error>> {
    let at_risk = ochids_at_risk(
        &jj::desc_of(repo, &sq.source)?,
        &jj::desc_of(repo, &sq.target)?,
    );
    if at_risk.is_empty() {
        return Ok(());
    }
    let listed = at_risk
        .iter()
        .map(|ochid| format!("  {ochid}"))
        .collect::<Vec<_>>()
        .join("\n");
    Err(format!(
        "refusing squash {} → {}: the squash would drop ochid: trailers\n\
         the destination's message lacks:\n\
         {listed}\n\
         merge the messages by hand (`jj describe {} -R {}`) or clear\n\
         the source's description, then retry",
        sq.source,
        sq.target,
        sq.target,
        repo.display(),
    )
    .into())
}

/// True when `rev` has no file changes and no description — nothing
/// worth squashing.
fn rev_is_empty_undescribed(repo: &Path, rev: &str) -> Result<bool, Box<dyn std::error::Error>> {
    if !jj::is_empty(repo, rev)? {
        return Ok(false);
    }
    Ok(jj::desc_of(repo, rev)?.is_empty())
}

/// Run the `squash-push` op: preflight, then squash (skipped when
/// the source is empty and undescribed) + bookmark-set + push.
///
/// - With an empty source and the bookmark already matching both
///   the squash target and the remote, reports "already sync'd"
///   and exits 0 — nothing to do.
/// - With an empty source but the remote behind, skips the squash
///   and still pushes.
pub fn squash_push(params: &SquashPushParams) -> Result<(), Box<dyn std::error::Error>> {
    debug!("squash_push: entry params={params:?}");
    let repo_str = params.repo.to_string_lossy().to_string();
    let cwd = std::path::Path::new(".");
    let sq = &params.squash;
    let bookmark = &params.bookmark;

    preflight(params)?;

    // Report an at-rest publish mismatch before touching anything
    // (0.69.0-3): the bookmark should match its origin counterpart
    // between runs, so a mismatch means an earlier publish was
    // lost. Publishing is this command's job, so it proceeds — the
    // report is the point, not a refusal. Suppressed when run as
    // push's `squash-push-bot` stage (see `report_publish_state`).
    if params.report_publish_state {
        match crate::common::bookmark_publish_state(&params.repo, bookmark)? {
            crate::common::PublishState::InSync => {}
            crate::common::PublishState::NeverPushed => info!(
                "squash-push: '{bookmark}' has never been pushed to origin — this run will publish it"
            ),
            crate::common::PublishState::Mismatch { local, remote } => warn!(
                "squash-push: '{bookmark}' ({}) does not match '{bookmark}@origin' ({}) — an \
                 earlier publish was likely lost; this run will publish it",
                &local[..local.len().min(12)],
                &remote[..remote.len().min(12)]
            ),
        }
    }

    // Empty-source handling: nothing to squash. If the bookmark
    // already matches both the target and the remote, nothing to
    // push either — report and exit 0.
    if rev_is_empty_undescribed(&params.repo, &sq.source)? {
        let target_cid = jj::cid_of(&params.repo, &sq.target)?;
        let bookmark_cid = jj::cid_of(&params.repo, bookmark)?;
        let remote_cid =
            jj::cid_of(&params.repo, &format!("{bookmark}@origin")).unwrap_or_default(); // OK: unresolvable remote bookmark (never pushed) → treated as not sync'd
        if bookmark_cid == target_cid && bookmark_cid == remote_cid {
            info!("squash-push: repo '{repo_str}' is already sync'd with remote");
            return Ok(());
        }
        info!(
            "squash-push: {} is empty — skipping squash, still pushing",
            sq.source
        );
    } else {
        info!("squash-push: squashing {} → {}...", sq.source, sq.target);
        run(
            "jj",
            &[
                "squash",
                "--ignore-immutable",
                "--use-destination-message",
                "--from",
                &sq.source,
                "--into",
                &sq.target,
                "-R",
                &repo_str,
            ],
            cwd,
        )?;
    }

    info!(
        "squash-push: setting bookmark '{bookmark}' to {}...",
        sq.target
    );
    jj::bookmark_set(&params.repo, bookmark, &sq.target)?;

    info!("squash-push: pushing '{bookmark}' to origin...");
    jj::git_push_bookmark(&params.repo, bookmark)?;

    info!("squash-push: done");
    Ok(())
}

#[cfg(test)]
mod tests {
    use std::path::PathBuf;

    use super::*;
    use crate::{Cli, Commands};
    use clap::Parser;

    fn parse(args: &[&str]) -> SquashPushArgs {
        let cli = Cli::try_parse_from(args).unwrap();
        match cli.command {
            Some(Commands::SquashPush(a)) => a,
            _ => panic!("expected SquashPush"),
        }
    }

    fn parse_err(args: &[&str]) -> String {
        Cli::try_parse_from(args).unwrap_err().to_string()
    }

    fn squash_at() -> SquashSpec {
        SquashSpec {
            source: "@".to_string(),
            target: "@-".to_string(),
        }
    }

    #[test]
    fn no_args_defaults() {
        let args = parse(&["vc-x1", "squash-push"]);
        assert_eq!(args.bookmark, "main");
        assert_eq!(args.repo, PathBuf::from("."));
        assert!(args.squash.value.is_none());
    }

    #[test]
    fn bookmark_positional() {
        let args = parse(&["vc-x1", "squash-push", "dev-0.14.0"]);
        assert_eq!(args.bookmark, "dev-0.14.0");
        assert_eq!(args.repo, PathBuf::from("."));
    }

    #[test]
    fn all_opts() {
        let cli = Cli::try_parse_from([
            "vc-x1",
            "--log",
            "/tmp/test.log",
            "squash-push",
            "dev-0.14.0",
            "-R",
            ".claude",
            "--squash",
            "@,@-",
        ])
        .unwrap();
        assert_eq!(cli.log, Some(PathBuf::from("/tmp/test.log")));
        if let Some(Commands::SquashPush(args)) = cli.command {
            assert_eq!(args.bookmark, "dev-0.14.0");
            assert_eq!(args.repo, PathBuf::from(".claude"));
            assert_eq!(args.squash.value, Some(squash_at()));
        } else {
            panic!("expected SquashPush");
        }
    }

    #[test]
    fn long_repo_flag() {
        let args = parse(&["vc-x1", "squash-push", "--repo", ".claude"]);
        assert_eq!(args.repo, PathBuf::from(".claude"));
    }

    #[test]
    fn bare_squash() {
        let args = parse(&["vc-x1", "squash-push", "--squash"]);
        assert_eq!(args.squash.value, Some(squash_at()));
    }

    #[test]
    fn bad_squash() {
        let err = parse_err(&["vc-x1", "squash-push", "--squash", "@"]);
        assert!(err.contains("expected SOURCE,TARGET"), "got: {err}");
    }

    #[test]
    fn retired_flags_rejected() {
        for flag in ["--detach", "--delay", "--exec", "--push"] {
            let err = parse_err(&["vc-x1", "squash-push", flag]);
            assert!(err.contains(flag), "flag {flag}: {err}");
        }
    }

    #[test]
    fn unknown_opt() {
        let err = parse_err(&["vc-x1", "squash-push", "--bogus"]);
        assert!(err.contains("--bogus"));
    }

    #[test]
    fn try_from_canonicalizes_and_defaults() {
        let args = parse(&["vc-x1", "squash-push"]);
        let params = SquashPushParams::try_from(&args).unwrap();
        assert_eq!(params.repo, std::fs::canonicalize(".").unwrap());
        assert_eq!(params.bookmark, "main");
        assert_eq!(params.squash, squash_at());
        assert!(params.report_publish_state, "CLI invocations report");
    }

    /// A lost publish (`main` moved without a push) is healed by a
    /// bare squash-push run: it reports the mismatch and publishes,
    /// leaving `main == main@origin`.
    #[test]
    fn squash_push_publishes_unpushed_bookmark_move() {
        use crate::test_helpers::{Fixture, jj_ok};

        let fx = Fixture::new("sp-heal");
        std::fs::write(fx.bot.join("lost.txt"), "lost session data\n").expect("write lost file");
        jj_ok(&fx.bot, &["commit", "-m", "lost bot commit"]);
        jj_ok(&fx.bot, &["bookmark", "set", "main", "-r", "@-"]);

        let params = SquashPushParams {
            repo: fx.bot.clone(),
            squash: squash_at(),
            bookmark: "main".to_string(),
            report_publish_state: true,
        };
        squash_push(&params).expect("squash-push should publish the lost commit");

        let cid = |rev: &str| {
            jj_ok(
                &fx.bot,
                &["log", "-r", rev, "--no-graph", "-T", "commit_id"],
            )
        };
        assert_eq!(cid("main"), cid("main@origin"), "main should be published");
    }

    #[test]
    fn ochids_at_risk_detects_source_only() {
        let source = "journal\n\nochid: /aaa\nochid: /bbb\n";
        let target = "previous journal\n\nochid: /aaa\n";
        assert_eq!(ochids_at_risk(source, target), vec!["/bbb"]);
    }

    #[test]
    fn ochids_at_risk_empty_cases() {
        // Undescribed source (the normal squash-push snapshot) is safe.
        assert!(ochids_at_risk("", "prev\n\nochid: /aaa\n").is_empty());
        // Source trailers all present in the destination are safe.
        let both = "msg\n\nochid: /aaa\n";
        assert!(ochids_at_risk(both, both).is_empty());
        // Source without trailers is safe regardless of destination.
        assert!(ochids_at_risk("described, no trailers\n", "prev\n").is_empty());
    }
}

//! The `sync` subcommand: fetch + classify + rebase / fast-forward
//! a workspace's repos against their remotes, then reposition `@`
//! onto the synced bookmark.
//!
//! `--bookmark` names a **work-repo** bookmark only: the bot
//! repo is a linear journal on `main` by design, so every
//! per-repo step (tracking preflight, classify, act, reposition)
//! resolves its bookmark via `repo_bookmark`, which pins the
//! bot repo to `main`.
//!
//! Sync is a single atomic operation — verify-then-act happens
//! inside one invocation against one fetch snapshot (a separate
//! check-then-apply pair of runs would race the remote). The
//! hidden deprecated `--check` flag preserves the old verify-only
//! mode for `push`'s preflight until that is rewired in-process.
//!
//! **Stop-on-error**: a failure leaves state where the failing step
//! stopped so the user can inspect it. Each repo's pre-sync op id
//! is persisted to `.vc-x1/sync-state.toml` (see `state`); the
//! error report points at `vc-x1 revert` to undo explicitly.
//!
//! `current_op_id` / `op_restore` are `pub(crate)` so `push` (and
//! the `revert` subcommand) reuse the same snapshot-and-restore
//! primitives.

use std::io::IsTerminal;
use std::path::{Path, PathBuf};

use clap::Args;
use log::{LevelFilter, debug, info, warn};

use crate::common::{default_scope, find_workspace_root, prompt, run, scope_to_repos};
use crate::context::Context;
use crate::jj;
use crate::options_flags::scope::{Scope, parse_scope};
use crate::subcommand::SubcommandRunner;

/// Fetch and sync a set of repos to their remotes.
///
/// One atomic operation: fetch, classify, fast-forward / rebase the
/// bookmark as needed, then reposition `@` onto it. On any failure
/// the starting state of every repo is restored via `jj op restore`.
///
/// Repo set is resolved from `-R/--repo` + `--scope`:
///
/// - `-R PATH` — workspace root, or a single repo to sync alone.
/// - `--scope=work|bot|work,bot` — keyword role selection,
///   resolved via the workspace root's `.vc-config.toml`.
/// - Neither — workspace-default scope:
///   - dual workspace (`.vc-config.toml` with `bot`) → `work,bot`
///   - single-repo workspace (`.vc-config.toml`, no `bot`) → `work`
///   - POR (no `.vc-config.toml`) → cwd
#[derive(Args, Debug)]
pub struct SyncArgs {
    /// Verify only — fetch + classify; error if any repo needs
    /// action; no bookmark move, no `@` reposition.
    ///
    /// Deprecated and hidden: kept solely for `push`'s preflight
    /// shell-out until that is rewired in-process (see the
    /// `TODO.md` sync follow-up). Note the fetch still
    /// auto-fast-forwards a tracked bookmark — this mode was never
    /// fully read-only.
    #[arg(long, hide = true)]
    pub check: bool,

    /// Suppress all informational output (exit code signals result)
    #[arg(short, long)]
    pub quiet: bool,

    /// Bookmark to sync in the work repo. The session (bot) repo
    /// is a linear journal and always syncs `main`, regardless.
    #[arg(long, default_value = "main")]
    pub bookmark: String,

    /// Remote to sync against
    #[arg(long, default_value = "origin")]
    pub remote: String,

    /// Rebase a non-empty `@` onto the synced bookmark without asking.
    ///
    /// After a successful sync, `@` is repositioned onto the synced
    /// bookmark. When the work repo's `@` carries changes it normally
    /// asks before rebasing; `--rebase` answers yes up front for
    /// non-interactive use. Ignored for the bot repo (which
    /// always `jj new main`).
    #[arg(long)]
    pub rebase: bool,

    /// Workspace root, or a single jj repo to sync on its own.
    ///
    /// - `-R PATH` alone — sync just the repo at PATH.
    /// - `-R PATH -s ROLES` — use PATH as the workspace root and
    ///   sync the named side(s).
    #[arg(short = 'R', long = "repo", value_name = "PATH", verbatim_doc_comment)]
    pub repo: Option<PathBuf>,

    /// Which repo(s) of the workspace to sync.
    ///
    /// `SCOPE=work|bot|work,bot`:
    ///
    /// - `work` — sync only the work repo.
    /// - `bot` — sync only the bot repo (errors if no bot repo
    ///   is configured).
    /// - `work,bot` — sync both repos.
    ///
    /// Composes with `-R` as the workspace root. Default depends
    /// on workspace state: dual workspace → `work,bot`;
    /// single-repo workspace or POR → `work`.
    #[arg(
        short = 's',
        long,
        value_name = "SCOPE",
        value_parser = parse_scope,
        verbatim_doc_comment
    )]
    pub scope: Option<Scope>,
}

/// Inputs to the sync op, flat, owned, clap-free.
///
/// - `quiet`: `-q` / `--quiet` — clamp output to `Warn` for the run.
/// - `bookmark`: bookmark to sync in the work repo (default
///   `main`); the bot repo always syncs `main`.
/// - `remote`: remote to sync against (default `origin`).
/// - `check`: hidden deprecated `--check` — verify-only mode
///   (fetch + classify + report, error if action needed; no
///   bookmark move, no `@` reposition). Absent ⇒ the normal
///   atomic sync.
/// - `rebase`: `--rebase` — rebase a non-empty `@` onto the synced
///   bookmark without prompting (work repo only; see
///   `reposition_work`).
/// - `repo`: `-R/--repo` path (None ⇒ discover the workspace
///   root from cwd).
/// - `scope`: `--scope` parsed (None ⇒ resolve via the
///   workspace-default scope at run time).
pub struct SyncParams {
    pub quiet: bool,
    pub bookmark: String,
    pub remote: String,
    pub check: bool,
    pub rebase: bool,
    pub repo: Option<PathBuf>,
    pub scope: Option<Scope>,
}

impl From<&SyncArgs> for SyncParams {
    /// Convert clap-derived `SyncArgs` into the flat `SyncParams`
    /// (total — every field copies straight over).
    fn from(a: &SyncArgs) -> Self {
        Self {
            quiet: a.quiet,
            bookmark: a.bookmark.clone(),
            remote: a.remote.clone(),
            check: a.check,
            rebase: a.rebase,
            repo: a.repo.clone(),
            scope: a.scope.clone(),
        }
    }
}

impl SubcommandRunner for SyncArgs {
    type Params = SyncParams;

    /// Delegate to the existing `From<&SyncArgs>` impl above
    /// (total — never fails).
    fn to_params(&self) -> Result<Self::Params, String> {
        Ok(SyncParams::from(self))
    }

    /// Run the existing `sync` op.
    fn run(ctx: &Context, params: &Self::Params) -> Result<(), Box<dyn std::error::Error>> {
        sync(ctx, params)
    }
}

/// Resolve a `-R`/`--scope` pair into a concrete repo list.
///
/// `-R` and `--scope` compose:
///
/// - neither — workspace-default scope against the discovered root.
/// - `-R PATH` alone — just that repo.
/// - `-s ROLES` alone — roles against the discovered workspace root.
/// - `-R PATH -s ROLES` — roles against `PATH` as the workspace root.
///
/// `pub(crate)` — shared by `sync` and `revert`, which must resolve
/// the same invocation shape to the same repos.
pub(crate) fn resolve_repos(
    repo: &Option<PathBuf>,
    scope: &Option<Scope>,
) -> Result<Vec<PathBuf>, Box<dyn std::error::Error>> {
    match (repo, scope) {
        (None, None) => {
            let root = find_workspace_root();
            scope_to_repos(&default_scope(root.as_deref()), root.as_deref())
        }
        (Some(p), None) => Ok(vec![p.clone()]),
        (None, Some(s)) => scope_to_repos(s, find_workspace_root().as_deref()),
        (Some(p), Some(s)) => scope_to_repos(s, Some(p)),
    }
}

/// Relationship between a local bookmark and its remote counterpart.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum State {
    /// Local and remote point at the same commit.
    UpToDate,
    /// Local is a strict ancestor of remote — fast-forward possible.
    Behind { local: String, remote: String },
    /// Remote is a strict ancestor of local — nothing to pull in.
    Ahead { local: String, remote: String },
    /// Neither is an ancestor of the other — needs rebase.
    Diverged { local: String, remote: String },
    /// The bookmark has no `@<remote>` counterpart.
    NoRemote,
}

/// Per-repo context accumulated between the snapshot and action phases.
#[derive(Debug)]
struct RepoCtx {
    path: PathBuf,
    #[allow(dead_code)]
    op_id: String,
    state: State,
}

/// CLI entry point for the `sync` subcommand.
///
/// Thin wrapper over `sync_repos` that resolves `--scope` into a
/// concrete repo list (falling back to the workspace-default
/// scope) and forwards the rest. Tests call `sync_repos` directly
/// with absolute fixture paths. `ctx` is unused today — present
/// for the uniform subcommand-layer signature.
///
/// When `--quiet` is set, the global log filter is temporarily
/// clamped to `Warn` for the duration of the call and restored on
/// return, so `info!` calls throughout sync (plus any
/// subprocess-stderr routed through `common::run`) go dark. Errors
/// still surface at `Warn` / `Error` so script callers don't lose
/// diagnostics.
pub fn sync(_ctx: &Context, params: &SyncParams) -> Result<(), Box<dyn std::error::Error>> {
    let repos = resolve_repos(&params.repo, &params.scope)?;
    if params.quiet {
        let prev = log::max_level();
        log::set_max_level(LevelFilter::Warn);
        let result = sync_repos(&repos, params);
        log::set_max_level(prev);
        result
    } else {
        sync_repos(&repos, params)
    }
}

/// Sync the given repos against their remotes.
///
/// Orchestrates the full flow: pre-flight clean-check on every repo,
/// snapshot each repo's current op id (persisted to
/// `.vc-x1/sync-state.toml` per repo), then hand off to `run_plan`
/// for fetch + classify + act, then reposition `@`.
///
/// **Stop-on-error**: a failure leaves every repo exactly where the
/// failing step stopped so the user can inspect what happened —
/// nothing is auto-reverted. The error report names each repo's
/// pre-sync op id and points at `vc-x1 revert`, which consumes the
/// persisted snapshots. On full success the snapshots are cleared
/// (a stale file must not become a revert target later).
///
/// Paths may be relative (resolved against the process cwd) or
/// absolute. Tests use absolute tempdir paths to avoid cwd dependence
/// under parallel `cargo test`.
pub fn sync_repos(
    repos: &[PathBuf],
    params: &SyncParams,
) -> Result<(), Box<dyn std::error::Error>> {
    debug!(
        "sync: enter (check={}, bookmark={}, remote={})",
        params.check, params.bookmark, params.remote
    );

    // Preflight: verify bookmark tracking on every repo before any
    // fetch/rebase. Implements "Non-tracking-remote bookmark detection"
    // — design at:
    //   https://github.com/winksaville/vc-x1/blob/main/notes/chores/chores-06.md#non-tracking-remote-bookmark-detection-design
    for repo in repos {
        let bookmark = repo_bookmark(repo, &params.bookmark);
        if bookmark != params.bookmark {
            info!(
                "{}: bot repo — syncing 'main' ('{}' is a work repo bookmark)",
                repo.display(),
                params.bookmark
            );
        }
        crate::common::verify_tracking(repo, bookmark)?;
    }

    let mut snapshots: Vec<(PathBuf, String)> = Vec::new();
    for repo in repos {
        let op_id = current_op_id(repo)?;
        debug!("{}: op snapshot = {op_id}", repo.display());
        state::save(
            repo,
            &op_id,
            repo_bookmark(repo, &params.bookmark),
            &params.remote,
        )?;
        snapshots.push((repo.clone(), op_id));
    }

    // Run the plan, then reposition `@` onto the freshly-synced
    // bookmark (skipped in deprecated verify-only mode). Both live
    // inside the same stop-on-error region: any failure falls
    // through to the report below with state left in place.
    let result = run_plan(&snapshots, params).and_then(|()| {
        if !params.check {
            for (repo, _) in &snapshots {
                reposition_at(repo, repo_bookmark(repo, &params.bookmark), params)?;
            }
        }
        Ok(())
    });

    if let Err(e) = &result {
        warn!("sync failed: {e}");
        warn!("stopping — state left as-is for inspection (no auto-revert)");
        warn!("pre-sync op snapshot per repo:");
        for (repo, op_id) in &snapshots {
            warn!("  {}: op {op_id}", repo.display());
        }
        warn!("undo with `vc-x1 revert`, or per repo: jj op restore <op> -R <repo>");
        debug!("sync: exit");
        return result;
    }

    // Full success — the snapshots are no longer revert targets.
    for (repo, _) in &snapshots {
        state::clear(repo)?;
    }

    debug!("sync: exit");
    Ok(())
}

/// Clean-case summary tail ("<N> repo(s) …" prefixed at the emit
/// site). Shared with main.rs's `long_about` so the documented
/// output shape can't drift from the emitted one.
pub const UP_TO_DATE_MSG: &str = "up to date, nothing to sync";

/// Fetch and classify each repo, then act (or not, in verify-only).
///
/// Returns `Err` on the first failure so the caller can stop and
/// report; partial progress across repos is left in place for
/// inspection (see `sync_repos`).
fn run_plan(
    snapshots: &[(PathBuf, String)],
    params: &SyncParams,
) -> Result<(), Box<dyn std::error::Error>> {
    // Phase 1 — fetch + classify silently.
    //
    // Each repo's fetch stderr is captured (rather than streamed to
    // `info!` via `common::run`) so we can decide after classification
    // whether to surface it. `jj git fetch`'s routine "Nothing
    // changed." chatter is the main thing we're suppressing here —
    // if nothing needs action, the user shouldn't see it.
    let mut fetched: Vec<(PathBuf, Vec<String>)> = Vec::new();
    let mut ctxs: Vec<RepoCtx> = Vec::new();
    for (repo, op_id) in snapshots {
        let lines = fetch_silent(repo, &params.remote)?;
        fetched.push((repo.clone(), lines));
        let state = classify(repo, repo_bookmark(repo, &params.bookmark), &params.remote)?;
        ctxs.push(RepoCtx {
            path: repo.clone(),
            op_id: op_id.clone(),
            state,
        });
    }

    let any_action_needed = ctxs
        .iter()
        .any(|c| matches!(c.state, State::Behind { .. } | State::Diverged { .. }));

    // Phase 2 — emit status. `--quiet` is enforced globally via the
    // log-level clamp in `sync()`, so these `info!` calls are already
    // suppressed in scripts; we just shape the output here.
    if !any_action_needed {
        let n = ctxs.len();
        let noun = if n == 1 { "repo is" } else { "repos are" };
        info!("sync: {n} {noun} {UP_TO_DATE_MSG}");
    } else {
        for (repo, lines) in &fetched {
            info!("{}: fetch {}", repo.display(), params.remote);
            for line in lines {
                info!("{line}");
            }
        }
        for ctx in &ctxs {
            log_state(&ctx.path, &ctx.state);
        }
    }

    // Phase 3 — act (subprocess output streams through as usual).
    // `act_on_state` short-circuits in deprecated verify-only mode,
    // making it a true no-op here. Repositioning `@` onto the synced
    // bookmark happens after `run_plan` returns (see `sync_repos`),
    // outside the revert region.
    for ctx in &ctxs {
        act_on_state(ctx, params)?;
    }

    // Phase 4 — verify-only mode is fatal when action would be
    // needed. The normal sync ran the action above and is done.
    if params.check && any_action_needed {
        let n_action = ctxs
            .iter()
            .filter(|c| matches!(c.state, State::Behind { .. } | State::Diverged { .. }))
            .count();
        let noun = if n_action == 1 { "repo" } else { "repos" };
        return Err(format!(
            "sync: {n_action} {noun} need action (see above) — \
             resolve with `vc-x1 sync` and re-run"
        )
        .into());
    }
    Ok(())
}

/// Fetch `repo` from `remote` without streaming chatter to `info!`.
///
/// The facade's in-process fetch returns one line per changed
/// remote bookmark; the caller decides whether to surface them
/// (action case) or drop them (clean case), which is what this
/// wrapper's stderr capture did in the spawned form.
fn fetch_silent(repo: &Path, remote: &str) -> Result<Vec<String>, Box<dyn std::error::Error>> {
    debug!("fetch --remote {remote} -R {}", repo.display());
    jj::git_fetch(repo, remote)
}

/// Reposition `@` onto the freshly-synced bookmark after a successful
/// sync.
///
/// Dispatches on repo role — the caller has already excluded the
/// deprecated verify-only mode:
///
/// - **session (bot) sub-repo** → always `jj new main`
///   (see `reposition_bot`).
/// - **any other repo** → move `@` onto the synced `bookmark` under
///   the work-repo safety rules (see `reposition_work`).
fn reposition_at(
    repo: &Path,
    bookmark: &str,
    params: &SyncParams,
) -> Result<(), Box<dyn std::error::Error>> {
    if is_bot_repo(repo) {
        reposition_bot(repo)
    } else {
        reposition_work(repo, bookmark, params.rebase)
    }
}

/// True when `repo` is the bot sub-repo.
///
/// Thin wrapper over `common::is_bot_dir` — side detection is by
/// location (the parent's config names this dir as its `bot`), not
/// config content. A POR / single-repo workspace is a work repo.
fn is_bot_repo(repo: &Path) -> bool {
    crate::common::is_bot_dir(repo)
}

/// Bookmark to sync for `repo`.
///
/// `--bookmark` is work-repo-only: the bot repo is a
/// linear journal on `main` by design, so it pins `main` regardless
/// of the requested bookmark. Every other repo uses `bookmark`
/// as passed.
fn repo_bookmark<'a>(repo: &Path, bookmark: &'a str) -> &'a str {
    if is_bot_repo(repo) { "main" } else { bookmark }
}

/// Reposition the bot repo's `@` onto `main`.
///
/// The session (`.claude`) repo is a linear journal on `main`, and its
/// `@` normally carries live session writes:
///
/// - `@-` already the `main` tip → no-op: `@` is where it belongs,
///   live writes stay in the working copy. (An unconditional
///   `jj new main` here would churn an empty `@`'s chid/op every
///   sync, or strand a non-empty `@`'s live writes — and any ochid
///   captured against its chid — on a sibling head.)
/// - Errors when `@-` isn't on `main` (not an ancestor-or-equal of the
///   bookmark) — refuse rather than guess.
/// - Otherwise `main` moved: `jj new main` starts a fresh `@` on the
///   bookmark; the prior `@` becomes a sibling head, which is
///   expected for the journal. A conflict is very unlikely given
///   `.claude`'s content; if one ever appears the user resolves it.
fn reposition_bot(repo: &Path) -> Result<(), Box<dyn std::error::Error>> {
    let parent = jj::cid_short_of(repo, "@-")?;
    let tip = jj::cid_short_of(repo, "main")?;
    if parent == tip {
        debug!("{}: @ already on 'main'", repo.display());
        return Ok(());
    }
    if !jj::matches(repo, &format!("{parent}::main"))? {
        return Err(format!(
            "{}: @- ({parent}) is not on main — refusing to reposition @",
            repo.display()
        )
        .into());
    }
    info!("{}: jj new main", repo.display());
    run(
        "jj",
        &["new", "main", "-R", &repo_str(repo)],
        Path::new("."),
    )?;
    Ok(())
}

/// Reposition the work repo's `@` onto the synced `bookmark`.
///
/// Let `@-` be the parent of `@`:
///
/// - `bookmark == @-` → already positioned; no-op.
/// - `bookmark` a proper descendant of `@-`, `@` empty →
///   `jj new bookmark` (jj auto-abandons the old empty `@`).
/// - `bookmark` a proper descendant of `@-`, `@` non-empty → rebase
///   `@` onto `bookmark`, but only with `rebase` set (else prompt on a
///   TTY; skip + inform when declined or not a TTY).
/// - `bookmark` not a descendant of `@-` (diverged / `@` ahead) →
///   leave `@` and inform why it didn't move.
fn reposition_work(
    repo: &Path,
    bookmark: &str,
    rebase: bool,
) -> Result<(), Box<dyn std::error::Error>> {
    let parent = jj::cid_short_of(repo, "@-")?;
    let tip = jj::cid_short_of(repo, bookmark)?;
    if tip == parent {
        debug!("{}: @ already on '{bookmark}'", repo.display());
        return Ok(());
    }
    if !jj::matches(repo, &format!("{parent}::{tip}"))? {
        info!(
            "{}: @- ({parent}) is not behind '{bookmark}' ({tip}); leaving @ in place",
            repo.display()
        );
        return Ok(());
    }
    // `bookmark` is a proper descendant of `@-` — safe to move a clean `@`.
    if at_is_empty(repo)? {
        info!("{}: jj new {bookmark}", repo.display());
        run(
            "jj",
            &["new", bookmark, "-R", &repo_str(repo)],
            Path::new("."),
        )?;
        return Ok(());
    }
    // `@` carries changes: rebase only on opt-in / confirmation.
    if !rebase && !confirm_rebase(repo)? {
        info!(
            "{}: @ has changes; left in place (pass --rebase to rebase onto '{bookmark}')",
            repo.display()
        );
        return Ok(());
    }
    info!("{}: rebasing @ onto '{bookmark}'", repo.display());
    run(
        "jj",
        &["rebase", "-b", "@", "-d", bookmark, "-R", &repo_str(repo)],
        Path::new("."),
    )?;
    if has_conflicts(repo)? {
        return Err(format!(
            "{}: rebase of @ onto '{bookmark}' produced conflicts",
            repo.display()
        )
        .into());
    }
    Ok(())
}

/// Ask whether to rebase a non-empty `@`, but only on a TTY.
///
/// Returns `Ok(false)` without prompting when stdin isn't a terminal
/// (scripts): the caller then skips + informs rather than blocking on
/// `read_line`. A `y`/`yes` (case-insensitive) answer confirms.
///
/// Under `cargo test` the harness inherits the invoking terminal's
/// stdin, so an in-process test reaching this path would block on
/// `read_line` waiting for the user — the `cfg!(test)` arm pins the
/// non-interactive answer instead.
fn confirm_rebase(repo: &Path) -> Result<bool, Box<dyn std::error::Error>> {
    if cfg!(test) || !std::io::stdin().is_terminal() {
        return Ok(false);
    }
    let ans = prompt(&format!(
        "{}: @ has changes — rebase onto the synced bookmark? [y/N] ",
        repo.display()
    ))?;
    Ok(matches!(ans.to_ascii_lowercase().as_str(), "y" | "yes"))
}

/// True when the working-copy commit `@` is empty (no changes).
fn at_is_empty(repo: &Path) -> Result<bool, Box<dyn std::error::Error>> {
    jj::matches(repo, "@ & empty()")
}

/// Perform the mutation corresponding to `ctx.state` (skipped in
/// deprecated verify-only mode).
///
/// - `UpToDate` / `Ahead` / `NoRemote` → no-op (and no output, the state
///   was already logged by `log_state`).
/// - `Behind` → `jj bookmark set <b> -r <b>@<remote>` to fast-forward.
/// - `Diverged` → `jj rebase -b <b> -d <b>@<remote>`, then probe
///   `conflicts()`. A non-empty result means the rebase produced
///   conflicted commits; return `Err` so the outer revert restores the
///   pre-fetch state.
fn act_on_state(ctx: &RepoCtx, params: &SyncParams) -> Result<(), Box<dyn std::error::Error>> {
    let repo = &ctx.path;
    let bookmark = repo_bookmark(repo, &params.bookmark);
    let remote_rev = format!("{}@{}", bookmark, params.remote);
    match &ctx.state {
        State::UpToDate | State::Ahead { .. } | State::NoRemote => Ok(()),
        State::Behind { .. } => {
            if !params.check {
                info!("{}: setting '{bookmark}' to {remote_rev}", repo.display());
                jj::bookmark_set(repo, bookmark, &remote_rev)?;
            }
            Ok(())
        }
        State::Diverged { local, remote } => {
            if !params.check {
                // `local` is either a single commit id or a comma-joined list
                // of heads when the bookmark is conflicted. Pick the head
                // that isn't the remote — that's the local-only tip. The
                // comma-joined path covers the jj post-fetch divergence
                // shape (local bookmark conflicted between old local head
                // and freshly-fetched remote head).
                let local_head = local
                    .split(',')
                    .find(|h| *h != remote)
                    .unwrap_or(local.as_str());
                info!(
                    "{}: rebasing {local_head} onto {remote_rev}",
                    repo.display()
                );
                run(
                    "jj",
                    &[
                        "rebase",
                        "-b",
                        local_head,
                        "-d",
                        &remote_rev,
                        "-R",
                        &repo_str(repo),
                    ],
                    Path::new("."),
                )?;
                if has_conflicts(repo)? {
                    return Err(format!("{}: rebase produced conflicts", repo.display()).into());
                }
            }
            Ok(())
        }
    }
}

/// Print a single-line summary of `state` at `info!` level.
fn log_state(repo: &Path, state: &State) {
    let r = repo.display();
    match state {
        State::UpToDate => info!("{r}: up-to-date"),
        State::NoRemote => info!("{r}: no remote counterpart — skipping"),
        State::Ahead { local, remote } => {
            info!("{r}: ahead (local {local} > remote {remote}); nothing to sync")
        }
        State::Behind { local, remote } => {
            info!("{r}: behind (local {local} < remote {remote}); fast-forward needed")
        }
        State::Diverged { local, remote } => {
            info!("{r}: diverged (local {local} vs remote {remote}); rebase needed")
        }
    }
}

/// Return the id of the most recent operation on `repo`.
///
/// Used as the revert target on failure. Exposed at `pub(crate)` so
/// `push` (0.37.0-2+) can reuse the same snapshot pattern for its
/// commit-stage rollback without duplicating the jj invocation.
pub(crate) fn current_op_id(repo: &Path) -> Result<String, Box<dyn std::error::Error>> {
    let out = run(
        "jj",
        &[
            "op",
            "log",
            "--no-graph",
            "-n",
            "1",
            "-T",
            "id.short(12)",
            "-R",
            &repo_str(repo),
        ],
        Path::new("."),
    )?;
    Ok(out.trim().to_string())
}

/// Restore `repo` to the operation identified by `op_id`.
///
/// Thin wrapper around `jj op restore` — drops the caller's returned
/// stdout. Exposed at `pub(crate)` for `push`'s commit-stage
/// rollback and the `revert` subcommand; sync itself no longer
/// auto-reverts (stop-on-error).
pub(crate) fn op_restore(repo: &Path, op_id: &str) -> Result<(), Box<dyn std::error::Error>> {
    run(
        "jj",
        &["op", "restore", op_id, "-R", &repo_str(repo)],
        Path::new("."),
    )?;
    Ok(())
}

/// Classify the relationship between `bookmark` and `bookmark@remote`.
///
/// Uses `bookmarks(<b>)` rather than the bare name so a conflicted
/// bookmark (jj's representation of a diverged fetch) resolves to all
/// of its heads instead of erroring. When the set has multiple heads,
/// the bookmark is conflicted and the repo is `Diverged` by definition.
/// Otherwise we compare the single local head against the single
/// remote commit via two revset-ancestry probes.
///
/// Returns `NoRemote` when `<b>@<remote>` does not resolve — the caller
/// logs a skip and moves on.
fn classify(
    repo: &Path,
    bookmark: &str,
    remote: &str,
) -> Result<State, Box<dyn std::error::Error>> {
    let local_heads = local_bookmark_heads(repo, bookmark)?;
    let remote_rev = format!("{bookmark}@{remote}");
    let Some(remote) = try_commit_id(repo, &remote_rev)? else {
        return Ok(State::NoRemote);
    };
    if local_heads.is_empty() {
        return Err(format!("{}: bookmark '{bookmark}' does not exist", repo.display()).into());
    }
    if local_heads.len() > 1 {
        // Conflicted bookmark — jj's shape for post-fetch divergence.
        let local = local_heads.join(",");
        return Ok(State::Diverged { local, remote });
    }
    let local = local_heads.into_iter().next().unwrap(); // OK: `len() > 1` arm handled above, `is_empty()` handled above
    if local == remote {
        return Ok(State::UpToDate);
    }
    let local_is_anc = jj::matches(repo, &format!("{local}::{remote_rev}"))?;
    let remote_is_anc = jj::matches(repo, &format!("{remote_rev}::{local}"))?;
    Ok(match (local_is_anc, remote_is_anc) {
        (true, _) => State::Behind { local, remote },
        (false, true) => State::Ahead { local, remote },
        (false, false) => State::Diverged { local, remote },
    })
}

/// Return all commit ids the `bookmark` currently points at.
///
/// Normally a one-element vector; two or more elements indicate a
/// conflicted bookmark (jj's representation of diverged post-fetch
/// state, where the local bookmark has multiple heads).
fn local_bookmark_heads(
    repo: &Path,
    bookmark: &str,
) -> Result<Vec<String>, Box<dyn std::error::Error>> {
    jj::cids_short_of(repo, &format!("bookmarks(exact:{bookmark})"))
}

/// Like `jj::cid_short_of`, but `Ok(None)` when the revset doesn't resolve.
///
/// The unresolvable-revision error (`jj::is_no_such_revision`,
/// typed in-process or by stderr wording when spawned) maps to
/// `Ok(None)` so callers can distinguish "missing" from "other
/// failure".
fn try_commit_id(repo: &Path, rev: &str) -> Result<Option<String>, Box<dyn std::error::Error>> {
    match jj::cid_short_of(repo, rev) {
        Ok(id) if id.is_empty() => Ok(None),
        Ok(id) => Ok(Some(id)),
        Err(e) if jj::is_no_such_revision(e.as_ref()) => Ok(None),
        Err(e) => Err(e),
    }
}

/// Return `true` when `repo` has any conflicted commits.
fn has_conflicts(repo: &Path) -> Result<bool, Box<dyn std::error::Error>> {
    jj::matches(repo, "conflicts()")
}

/// Convert a path to a `String` suitable for passing as a subprocess arg.
fn repo_str(p: &Path) -> String {
    p.to_string_lossy().into_owned()
}

pub(crate) mod state;

#[cfg(test)]
mod tests;

#[cfg(test)]
mod integration_tests;

//! `SubcommandRunner` trait
//!
//! The purpose is to simplify invoking a subcommand so `main`
//! can invoke any subcommand with one line:
//!
//! `Commands::Chid(args) => args.dispatch(&ctx),`
//!
//! Instead of the ~11 lines that the default `dispatch` below
//! now encapsulates.
//!
//! Implementors provide:
//!
//! - [`SubcommandRunner::to_params`] — build the clap-free
//!   `Params` from the clap `Args` (covers both `From` /
//!   `TryFrom` shapes uniformly via `Result<_, String>`).
//! - [`SubcommandRunner::run`] — the subcommand body.
//!
//! The default [`SubcommandRunner::dispatch`] builds `Params`
//! via `to_params`, runs via `run`, and maps the result to
//! `ExitCode`. Errors at any stage log via `error!` and return
//! `ExitCode::FAILURE`. `Context` is loaded once in `main` and
//! passed in by reference so a single `Context` is shared across
//! the (one) match arm that actually runs.
//!
//! ## See also
//!
//! - The wider CLI-args / subcommand-layer split this trait
//!   formalizes: [`ARCHITECTURE.md > args → Context + Params`][arch].
//! - Cycle design, ladder, evaluation gate:
//!   [`chores-10.md > 0.50.0-0`][open].
//! - Worked example, trait-shape decisions, naming:
//!   [`chores-10.md > 0.50.0-1`][port].
//! - First implementor: [`crate::chid`].
//!
//! [arch]: https://github.com/winksaville/vc-x1/blob/main/ARCHITECTURE.md#args--context--params
//! [open]: https://github.com/winksaville/vc-x1/blob/main/notes/chores/chores-10.md#chore-open-subcommand-trait-sweep-0500-0
//! [port]: https://github.com/winksaville/vc-x1/blob/main/notes/chores/chores-10.md#refactor-subcommandrunner-trait--chid-0500-1

use std::process::ExitCode;

use log::error;

use crate::context::Context;

/// Trait implemented by every subcommand's clap `Args` type so
/// `main.rs` can dispatch via a single `args.dispatch(&ctx)`
/// call.
pub trait SubcommandRunner {
    /// The clap-free `Params` struct the subcommand body
    /// consumes.
    type Params;

    /// Build `Params` from `Args`. `Result<_, String>` absorbs
    /// both `From` (return `Ok(...)`) and `TryFrom` (forward
    /// the error) shapes uniformly.
    fn to_params(&self) -> Result<Self::Params, String>;

    /// Run the subcommand body.
    fn run(ctx: &Context, params: &Self::Params) -> Result<(), Box<dyn std::error::Error>>;

    /// Default dispatch: build `Params` via `to_params`, bracket
    /// the run with `crate::bm_track` enter/exit, execute via
    /// `run`, and map the result to `ExitCode`. Errors at any
    /// stage log via `error!` and return `ExitCode::FAILURE`.
    /// `bm_track` itself emits at `debug!`, so default runs stay
    /// quiet — no per-call gate is needed here.
    fn dispatch(&self, ctx: &Context) -> ExitCode {
        let params = match self.to_params() {
            Ok(p) => p,
            Err(e) => {
                error!("{e}");
                return ExitCode::FAILURE;
            }
        };

        // Command name is the first positional after the binary;
        // clap has already validated it by the time we reach
        // dispatch (top-level parse errors exit earlier).
        let command_name = std::env::args().nth(1).unwrap_or_else(|| "?".to_string()); // OK: default when somehow invoked without a subcommand

        crate::bm_track("enter", &command_name);
        let exit_code = match Self::run(ctx, &params) {
            Ok(()) => ExitCode::SUCCESS,
            Err(e) => {
                error!("{e}");
                ExitCode::FAILURE
            }
        };
        crate::bm_track("exit ", &command_name);
        exit_code
    }
}

