1	//! Shared test helpers for dual-repo integration tests.
2	//!
3	//! Provides a `Fixture` that wraps `crate::init::init`
4	//! plus a per-process unique-tempdir helper so parallel tests don't
5	//! collide. Lifted out of the `sync` test module (originally inline at
6	//! `sync.rs:521–560`) so `push`'s tests (0.37.0) and any future
7	//! subcommand's tests can sit on the same harness without
8	//! copy-paste drift.
9	//!
10	//! Test-only — the whole module is gated at its declaration site via
11	//! `#[cfg(test)] mod test_helpers;`.
12	
13	use std::fs;
14	use std::path::{Path, PathBuf};
15	use std::sync::atomic::{AtomicU64, Ordering};
16	use std::time::{SystemTime, UNIX_EPOCH};
17	
18	use crate::common::write_file;
19	use crate::config::RepoSelector;
20	use crate::context::Context;
21	use crate::init::{InitArgs, InitParams, init};
22	use crate::options_flags::account::AccountOption;
23	use crate::options_flags::config::ConfigOption;
24	use crate::options_flags::por::PorFlag;
25	use crate::options_flags::provision_bundle::ProvisionOptionFlagBundle;
26	use crate::options_flags::repo::RepoOption;
27	use crate::options_flags::use_template::UseTemplateOption;
28	use crate::test_tmp_root::{resolve_tmp_root, should_keep_tempdir};
29	
30	/// Per-process counter so same-nanosecond tempdir collisions yield
31	/// distinct paths when tests run in parallel.
32	static COUNTER: AtomicU64 = AtomicU64::new(0);
33	
34	/// Run `jj <args> -R <repo>` in a test, asserting success; return
35	/// trimmed stdout.
36	///
37	/// The one copy — the per-module variants migrated here at
38	/// 0.73.0-4 (the DRY-facade cycle's test-dedup step). Spawns
39	/// directly rather than calling `crate::jj` so test inspection
40	/// stays independent of the facade under test.
41	pub fn jj_ok(repo: &Path, args: &[&str]) -> String {
42	    let out = std::process::Command::new("jj")
43	        .args(args)
44	        .arg("-R")
45	        .arg(repo)
46	        .output()
47	        .expect("spawn jj");
48	    assert!(
49	        out.status.success(),
50	        "jj {args:?} failed in {}: {}",
51	        repo.display(),
52	        String::from_utf8_lossy(&out.stderr)
53	    );
54	    String::from_utf8_lossy(&out.stdout).trim().to_string()
55	}
56	
57	/// 12-character commit id of `rev` (test inspection).
58	pub fn cid(repo: &Path, rev: &str) -> String {
59	    jj_ok(
60	        repo,
61	        &["log", "-r", rev, "--no-graph", "-T", "commit_id.short(12)"],
62	    )
63	}
64	
65	/// 12-character change id of `rev` (test inspection).
66	pub fn chid(repo: &Path, rev: &str) -> String {
67	    jj_ok(
68	        repo,
69	        &["log", "-r", rev, "--no-graph", "-T", "change_id.short(12)"],
70	    )
71	}
72	
73	/// Full description of `rev` (test inspection).
74	pub fn description(repo: &Path, rev: &str) -> String {
75	    jj_ok(repo, &["log", "-r", rev, "--no-graph", "-T", "description"])
76	}
77	
78	/// Build a unique tempdir path for a test fixture.
79	///
80	/// Combines a nanosecond timestamp with a per-process atomic counter
81	/// so parallel tests and same-nanosecond collisions both yield
82	/// distinct paths. Prefix is `vc-x1-test-<tag>-<ts>-<n>` so callers
83	/// from different subcommand tests stay discoverable in `$TMPDIR`.
84	pub fn unique_base(tag: &str) -> PathBuf {
85	    let ts = SystemTime::now()
86	        .duration_since(UNIX_EPOCH)
87	        .map(|d| d.as_nanos())
88	        .unwrap_or(0); // OK: clock error → 0 is harmless for unique tempdir naming
89	    let n = COUNTER.fetch_add(1, Ordering::SeqCst);
90	    resolve_tmp_root().join(format!("vc-x1-test-{tag}-{ts}-{n}"))
91	}
92	
93	/// Owned dual-repo fixture with RAII cleanup.
94	///
95	/// Builds a fresh throwaway dual-repo set under a unique tempdir
96	/// by driving `init::init` with a path TARGET and `--repo
97	/// local=<base>` (so config lookup is skipped via the
98	/// resolve_repo short-circuit). `create_symlink=false` suppresses
99	/// the `~/.claude/projects/` side effect. Exposes the two repo
100	/// paths (`work` and `work/.claude`). The tempdir tree is removed
101	/// when the value is dropped, so a panicking test still cleans up
102	/// after itself.
103	pub struct Fixture {
104	    /// Root tempdir that owns both repos and their bare-git remotes.
105	    pub base: PathBuf,
106	    /// Work repo path (`<base>/work`).
107	    pub work: PathBuf,
108	    /// Bot repo path (`<base>/work/.claude`).
109	    pub bot: PathBuf,
110	}
111	
112	impl Fixture {
113	    /// Build a fresh fixture in a unique tempdir.
114	    pub fn new(tag: &str) -> Self {
115	        Self::new_opts(tag, false, None)
116	    }
117	
118	    /// Build a fresh fixture with optional pending changes and a
119	    /// template seed.
120	    ///
121	    /// - `with_pending` — after init, write a small file into each
122	    ///   repo so `@` carries uncommitted changes (useful for
123	    ///   squash-push / push tests).
124	    /// - `use_template` — `WORK[,BOT]` forwarded to init.
125	    pub fn new_opts(tag: &str, with_pending: bool, use_template: Option<String>) -> Self {
126	        let base = unique_base(tag);
127	        // init refuses to reuse an existing project_dir, so `base`
128	        // must not exist yet. `unique_base` already guarantees that.
129	        //
130	        // Path TARGET = `<base>/work` (workspace destination); the
131	        // basename ("work") becomes the repo name. `--repo local=<base>`
132	        // sets the bare-repo parent so the layout mirrors the old
133	        // `--repo-local <base>` + NAME=`work` shape:
134	        //   <base>/work/                  (work repo)
135	        //   <base>/work/.claude/          (bot repo)
136	        //   <base>/remote-work.git        (work bare origin)
137	        //   <base>/remote-work.claude.git      (bot bare origin)
138	        let work_path = base.join("work");
139	        let args = InitArgs {
140	            target: work_path.to_string_lossy().into_owned(),
141	            name: None,
142	            account: AccountOption::default(),
143	            repo: RepoOption {
144	                value: Some(RepoSelector {
145	                    category: "local".to_string(),
146	                    value: Some(base.to_string_lossy().into_owned()),
147	                }),
148	            },
149	            por: PorFlag { value: false },
150	            provision: ProvisionOptionFlagBundle::default(),
151	            use_template: UseTemplateOption {
152	                value: use_template,
153	            },
154	            config: ConfigOption::default(),
155	        };
156	        let ctx = Context::load().expect("load user config for test fixture");
157	        let mut params = InitParams::from(&args);
158	        params.create_symlink = false;
159	        init(&ctx, &params).expect("build test fixture via init");
160	
161	        let work = base.join("work");
162	        let bot = work.join(".claude");
163	
164	        if with_pending {
165	            write_file(&work.join("TODO.md"), "# TODO\n- first feature\n")
166	                .expect("write pending TODO.md");
167	            write_file(
168	                &bot.join("session-notes.md"),
169	                "# Session notes\n- simulated pending work\n",
170	            )
171	            .expect("write pending session-notes.md");
172	        }
173	
174	        Fixture { base, work, bot }
175	    }
176	
177	    /// Convenience: return both repo paths as a `Vec<PathBuf>`
178	    /// suitable for `sync_repos` (or any other `&[PathBuf]` API).
179	    pub fn repos(&self) -> Vec<PathBuf> {
180	        vec![self.work.clone(), self.bot.clone()]
181	    }
182	}
183	
184	impl Drop for Fixture {
185	    /// Remove the fixture tree on drop. Best-effort; a failure here
186	    /// doesn't fail the test. Suppressed when `$VC_X1_TEST_KEEP` is
187	    /// set — see `test_tmp_root::should_keep_tempdir`.
188	    fn drop(&mut self) {
189	        if should_keep_tempdir() {
190	            eprintln!("VC_X1_TEST_KEEP set; preserving {}", self.base.display());
191	        } else {
192	            let _ = fs::remove_dir_all(&self.base);
193	        }
194	    }
195	}
196	
197	/// Owned single-repo (POR) fixture with RAII cleanup.
198	///
199	/// Sibling of `Fixture` for `--por` flows. Drives
200	/// `init::init` with `por: true` and a path TARGET;
201	/// `--repo local=<base>` steers the bare origin to
202	/// `<base>/remote.git` (vs. dual's `remote-work.git` /
203	/// `remote-work.claude.git`). No `.claude/` peer, no symlink.
204	///
205	/// Field shape differs from `Fixture` — there is no `bot` peer
206	/// path — so it's a distinct type rather than an `Option<PathBuf>`
207	/// on `Fixture` (the latter would force every dual-using caller to
208	/// `.unwrap()` or pattern-match).
209	pub struct FixturePor {
210	    /// Root tempdir that owns the repo and its bare-git remote.
211	    pub base: PathBuf,
212	    /// POR repo path (`<base>/work`).
213	    pub work: PathBuf,
214	}
215	
216	impl FixturePor {
217	    /// Build a fresh POR fixture in a unique tempdir.
218	    pub fn new(tag: &str) -> Self {
219	        Self::new_with_config(tag, None)
220	    }
221	
222	    /// Build a fresh POR fixture, threading `config` through to
223	    /// `InitArgs` for `--config` variant testing.
224	    pub fn new_with_config(tag: &str, config: Option<String>) -> Self {
225	        let base = unique_base(tag);
226	        // Path TARGET = `<base>/work`; basename ("work") becomes
227	        // the repo name. `--repo local=<base>` sets the bare-repo
228	        // parent, producing the layout:
229	        //   <base>/work/        (POR repo)
230	        //   <base>/remote.git   (bare origin)
231	        let work_path = base.join("work");
232	        let args = InitArgs {
233	            target: work_path.to_string_lossy().into_owned(),
234	            name: None,
235	            account: AccountOption::default(),
236	            repo: RepoOption {
237	                value: Some(RepoSelector {
238	                    category: "local".to_string(),
239	                    value: Some(base.to_string_lossy().into_owned()),
240	                }),
241	            },
242	            por: PorFlag { value: true },
243	            provision: ProvisionOptionFlagBundle::default(),
244	            use_template: UseTemplateOption::default(),
245	            config: ConfigOption { value: config },
246	        };
247	        let ctx = Context::load().expect("load user config for POR test fixture");
248	        let mut params = InitParams::from(&args);
249	        params.create_symlink = false;
250	        init(&ctx, &params).expect("build test fixture via init (POR)");
251	
252	        let work = base.join("work");
253	        FixturePor { base, work }
254	    }
255	}
256	
257	impl Drop for FixturePor {
258	    /// Remove the fixture tree on drop. Best-effort; a failure here
259	    /// doesn't fail the test. Suppressed when `$VC_X1_TEST_KEEP` is
260	    /// set — see `test_tmp_root::should_keep_tempdir`.
261	    fn drop(&mut self) {
262	        if should_keep_tempdir() {
263	            eprintln!("VC_X1_TEST_KEEP set; preserving {}", self.base.display());
264	        } else {
265	            let _ = fs::remove_dir_all(&self.base);
266	        }
267	    }
268	}
