1	//! Integration tests for the push module.
2	//!
3	//! End-to-end tests for `push_in` against real dual-repo jj
4	//! fixtures (bare-git remotes + colocated jj repos under a
5	//! unique tempdir via `crate::test_helpers::Fixture`).
6	//!
7	//! Most tests use `--from message` to skip `preflight` — its
8	//! `sync --check` step re-invokes `current_exe()`, which under
9	//! `cargo test` is the test harness, not the CLI binary. Most
10	//! also use `--no-squash-push`
11	//! to focus on the earlier stages (message, commit-work,
12	//! commit-bot, bookmark-set, push-work); the
13	//! `push_squash_push_bot_*` tests run the in-process
14	//! `squash-push-bot` stage for real. Everything is exercised
15	//! against the fixture's local bare-git remotes.
16	//!
17	//! Stage execution + rollback are covered here;
18	//! state-file / layout / stage-ordering mechanics are covered
19	//! in the neighboring `tests` module via pure unit tests.
20	//!
21	//! Requires `jj` and the compiled `vc-x1` binary in `PATH`.
22	
23	use super::*;
24	use crate::test_helpers::{Fixture, chid, cid, description, jj_ok};
25	use std::fs;
26	
27	/// First line of a revision's description.
28	fn desc_first_line(repo: &Path, rev: &str) -> String {
29	    jj_ok(
30	        repo,
31	        &[
32	            "log",
33	            "-r",
34	            rev,
35	            "--no-graph",
36	            "-T",
37	            "description.first_line()",
38	        ],
39	    )
40	}
41	
42	/// Standard test params: bookmark=main, `--no-squash-push` (skip
43	/// the bot-repo squash+push), `--yes` (auto-approve any interactive
44	/// prompts).
45	fn test_params(title: &str, body: &str) -> PushParams {
46	    PushParams {
47	        bookmark: Some("main".to_string()),
48	        step: false,
49	        no_squash_push: true,
50	        dry_run: false,
51	        title: Some(title.to_string()),
52	        body: Some(body.to_string()),
53	        yes: true,
54	    }
55	}
56	
57	/// Happy path when `.claude` has no pending changes: the work
58	/// commit lands with an `ochid` trailer pointing at `.claude`'s
59	/// pre-existing `@-`, `commit-bot` is skipped, and both
60	/// `bookmark-set` + `push-work` still run cleanly.
61	#[test]
62	fn push_happy_bot_clean() {
63	    let fx = Fixture::new("push-clean");
64	    fs::write(fx.work.join("hello.txt"), "hi").expect("write work file");
65	
66	    let bot_main_before = cid(&fx.bot, "main");
67	
68	    push_in(&fx.work, &test_params("feat: clean case", "work body")).expect("push should succeed");
69	
70	    // Work repo: main advanced to our new commit.
71	    assert_eq!(desc_first_line(&fx.work, "main"), "feat: clean case");
72	    let work_full = description(&fx.work, "main");
73	    assert!(
74	        work_full.contains("ochid: /.claude/"),
75	        "work ochid trailer missing:\n{work_full}"
76	    );
77	
78	    // `.claude` main unchanged (no commit happened there).
79	    assert_eq!(
80	        cid(&fx.bot, "main"),
81	        bot_main_before,
82	        ".claude main should not have moved"
83	    );
84	}
85	
86	/// bugs.md #4: a work repo whose `@` is empty (the rung was
87	/// committed by hand before invoking push) must not mint a
88	/// stamped empty duplicate on top of the real commit. The
89	/// pre-made commit is published as-is and the bot's ochid points
90	/// at *it*, not at a duplicate.
91	#[test]
92	fn push_empty_work_at_skips_commit_work() {
93	    let fx = Fixture::new("push-empty-work");
94	    fs::write(fx.work.join("hand.txt"), "hand-made").expect("write work file");
95	    jj_ok(
96	        &fx.work,
97	        &["commit", "-m", "feat: committed by hand", "-m", "body"],
98	    );
99	    fs::write(fx.bot.join("session.jsonl"), "{\"line\":1}\n").expect("write session file");
100	
101	    let hand_chid = chid(&fx.work, "@-");
102	
103	    push_in(
104	        &fx.work,
105	        &test_params("feat: would duplicate", "ignored body"),
106	    )
107	    .expect("push should succeed");
108	
109	    // The hand-made commit is what the bookmark publishes — no
110	    // empty duplicate carrying the supplied title on top of it.
111	    assert_eq!(desc_first_line(&fx.work, "main"), "feat: committed by hand");
112	    assert_eq!(chid(&fx.work, "main"), hand_chid);
113	
114	    // The bot commit's ochid names the real commit, not a duplicate.
115	    let bot_full = description(&fx.bot, "main");
116	    assert!(
117	        bot_full.contains(&format!("ochid: /{hand_chid}")),
118	        "bot ochid should point at the hand-made commit {hand_chid}:\n{bot_full}"
119	    );
120	}
121	
122	/// Happy path when `.claude` has pending changes: both repos
123	/// commit, each with an ochid trailer pointing at the other.
124	#[test]
125	fn push_happy_bot_dirty() {
126	    let fx = Fixture::new("push-dirty");
127	    fs::write(fx.work.join("work.txt"), "work").expect("write work file");
128	    fs::write(fx.bot.join("session.jsonl"), "{\"line\":1}\n").expect("write session file");
129	
130	    let bot_main_before = cid(&fx.bot, "main");
131	
132	    push_in(&fx.work, &test_params("feat: paired change", "paired body"))
133	        .expect("push should succeed");
134	
135	    // Both repos have new commits with matching titles.
136	    assert_eq!(desc_first_line(&fx.work, "main"), "feat: paired change");
137	    assert_eq!(desc_first_line(&fx.bot, "main"), "feat: paired change");
138	
139	    // Cross-repo ochid trailers are both present.
140	    let work_full = description(&fx.work, "main");
141	    let bot_full = description(&fx.bot, "main");
142	    assert!(
143	        work_full.contains("ochid: /.claude/"),
144	        "work ochid missing:\n{work_full}"
145	    );
146	    // `.claude`'s ochid points at the work repo, so the prefix is
147	    // just `/` (no `.claude` segment).
148	    assert!(
149	        bot_full
150	            .lines()
151	            .any(|l| l.starts_with("ochid: /") && !l.starts_with("ochid: /.claude/")),
152	        ".claude ochid should point at work repo:\n{bot_full}"
153	    );
154	
155	    // `.claude` main moved off its initial commit.
156	    assert_ne!(
157	        cid(&fx.bot, "main"),
158	        bot_main_before,
159	        ".claude main should have advanced"
160	    );
161	}
162	
163	/// The real `squash-push-bot` stage: a full push (no
164	/// `--no-squash-push`) squashes `.claude`'s tail and pushes `main`
165	/// to the bot repo's origin in-process — synchronously, no
166	/// detached child (the 0.68.1-diagnosed loss).
167	#[test]
168	fn push_squash_push_bot_inline_pushes_bot_main() {
169	    let fx = Fixture::new("push-sp-inline");
170	    fs::write(fx.work.join("work.txt"), "work").expect("write work file");
171	    fs::write(fx.bot.join("session.jsonl"), "{\"line\":1}\n").expect("write session file");
172	
173	    let mut params = test_params("feat: inline squash-push", "body");
174	    params.no_squash_push = false;
175	    push_in(&fx.work, &params).expect("push should succeed");
176	
177	    // Bot commit reached the bare origin before push returned.
178	    assert_eq!(
179	        cid(&fx.bot, "main@origin"),
180	        cid(&fx.bot, "main"),
181	        ".claude main should be pushed to origin"
182	    );
183	    // Working copy is clean after the tail squash.
184	    assert_eq!(
185	        jj_ok(&fx.bot, &["log", "-r", "@", "--no-graph", "-T", "empty"]),
186	        "true",
187	        ".claude @ should be empty after squash-push-bot"
188	    );
189	}
