191	/// A tail (session write landing after `commit-bot`) is
192	/// folded into the bot commit by the stage's squash —
193	/// preserving the commit's change id so work-side `ochid:`
194	/// trailers stay valid — and pushed.
195	#[test]
196	fn push_squash_push_bot_folds_micro_tail() {
197	    let fx = Fixture::new("push-sp-tail");
198	    fs::write(fx.work.join("work.txt"), "work").expect("write work file");
