267	    // are `name: ...`; match on the name position, not the whole
268	    // line — commit titles may legitimately contain "feature").
269	    let bot_bookmarks = jj_ok(&fx.bot, &["bookmark", "list"]);
270	    assert!(
271	        !bot_bookmarks.lines().any(|l| l.starts_with("feature:")),
272	        ".claude must not grow a 'feature' bookmark:\n{bot_bookmarks}"
273	    );
274	}
