276	/// `rollback_on_failure` rewinds both repos to their recorded
277	/// `jj op` snapshots when triggered mid-flow.
278	///
279	/// Simulates a failure after both repos have had their `main`
280	/// bookmark advanced past the original position, then calls
281	/// `rollback_on_failure` with the pre-mutation op IDs. After
282	/// rollback, `main` should be back at the starting commit in
283	/// both repos.
284	///
285	/// Notes:
286	/// - We don't compare `current_op_id` post-rollback because
287	///   reading the op id snapshots the (still-dirty) working
288	///   copy, creating a fresh op. Bookmark position is the
289	///   load-bearing invariant anyway.
290	/// - Each mutation sequence actually moves `main` (describe →
291	///   bookmark set → new) so the pre-rollback state is
292	///   observably different from the post-rollback state.
293	#[test]
294	fn push_rollback_restores_both_repos() {
295	    let fx = Fixture::new("push-rollback");
296	
297	    // Snapshot pre-mutation state.
298	    let op_work_start = current_op_id(&fx.work).expect("work op id");
299	    let op_bot_start = current_op_id(&fx.bot).expect("bot op id");
300	    let main_work_start = cid(&fx.work, "main");
301	    let main_bot_start = cid(&fx.bot, "main");
302	
303	    // Mutate both repos so `main` actually advances (this is
304	    // what rollback has to undo).
305	    fs::write(fx.work.join("work.txt"), "work").expect("write");
306	    fs::write(fx.bot.join("session.jsonl"), "{}\n").expect("write");
307	    jj_ok(&fx.work, &["describe", "-m", "test commit"]);
308	    jj_ok(&fx.work, &["bookmark", "set", "main", "-r", "@"]);
309	    jj_ok(&fx.work, &["new"]);
310	    jj_ok(&fx.bot, &["describe", "-m", "test session"]);
311	    jj_ok(&fx.bot, &["bookmark", "set", "main", "-r", "@"]);
312	    jj_ok(&fx.bot, &["new"]);
313	
314	    // Sanity: main has advanced in both repos.
315	    assert_ne!(
316	        cid(&fx.work, "main"),
317	        main_work_start,
318	        "setup should have moved work main"
319	    );
320	    assert_ne!(
321	        cid(&fx.bot, "main"),
322	        main_bot_start,
323	        "setup should have moved .claude main"
324	    );
325	
326	    // Snapshots from before any of the above mutations.
327	    let snapshots = Snapshots {
328	        work: op_work_start,
329	        bot: op_bot_start,
330	    };
331	
332	    let err: Box<dyn std::error::Error> = "forced for test".into();
333	    rollback_on_failure(&fx.work, &snapshots, err.as_ref());
334	
335	    // After rollback, `main` is restored in both repos.
336	    assert_eq!(cid(&fx.work, "main"), main_work_start);
337	    assert_eq!(cid(&fx.bot, "main"), main_bot_start);
338	}
339	
340	/// Build a `Run` carrying the chids a completed push would have.
341	fn completion_run(work_chid: String, bot_chid: String) -> Run {
342	    Run {
343	        title: String::new(),
344	        body: String::new(),
345	        work_chid,
346	        bot_chid,
347	        bot_had_changes: false,
348	    }
349	}
350	
351	/// Happy path: bookmarks at the run's chids, work working copy
352	/// clean. `verify_completion` returns Ok.
353	#[test]
354	fn completion_sanity_pass() {
355	    let fx = Fixture::new("completion-pass");
356	    // Run a real push so the world is in the post-completion shape.
357	    fs::write(fx.work.join("work.txt"), "x").expect("write work file");
358	    push_in(&fx.work, &test_params("feat: pass", "body")).expect("push");
359	
360	    let work_chid = chid(&fx.work, "main");
361	    let bot_chid = chid(&fx.bot, "main");
362	    let run = completion_run(work_chid, bot_chid);
363	
364	    verify_completion(&fx.work, "main", &run).expect("post-completion verification passes");
365	}
366	
367	/// Check 1 fail: the run's work_chid doesn't match the bookmark.
368	#[test]
369	fn completion_sanity_fail_work_chid_mismatch() {
370	    let fx = Fixture::new("completion-fail-work");
371	    fs::write(fx.work.join("work.txt"), "x").expect("write work file");
372	    push_in(&fx.work, &test_params("feat: x", "body")).expect("push");
373	
