379	        verify_completion(&fx.work, "main", &run).expect_err("bogus work_chid should fail check 1");
380	    let msg = err.to_string();
381	    assert!(msg.contains("work bookmark"), "msg: {msg}");
382	    assert!(msg.contains("zzzzzzzzzzzz"), "msg: {msg}");
383	}
384	
385	/// Check 2 fail: work working copy has uncommitted changes.
386	#[test]
387	fn completion_sanity_fail_dirty_wc() {
388	    let fx = Fixture::new("completion-fail-dirty");
389	    fs::write(fx.work.join("work.txt"), "x").expect("write work file");
390	    push_in(&fx.work, &test_params("feat: x", "body")).expect("push");
391	    // Now dirty the working copy after push completed.
392	    fs::write(fx.work.join("dirty.txt"), "uncommitted").expect("write dirty");
393	
394	    let work_chid = chid(&fx.work, "main");
395	    let bot_chid = chid(&fx.bot, "main");
