397	
398	    let err = verify_completion(&fx.work, "main", &run)
399	        .expect_err("dirty working copy should fail check 2");
400	    let msg = err.to_string();
401	    assert!(msg.contains("uncommitted changes"), "msg: {msg}");
402	}
403	
404	/// Check 3 fail: the run's bot_chid doesn't match .claude's bookmark.
405	#[test]
406	fn completion_sanity_fail_bot_chid_mismatch() {
407	    let fx = Fixture::new("completion-fail-claude");
408	    fs::write(fx.work.join("work.txt"), "x").expect("write work file");
409	    push_in(&fx.work, &test_params("feat: x", "body")).expect("push");
410	
411	    let work_chid = chid(&fx.work, "main");
412	    let run = completion_run(work_chid, "zzzzzzzzzzzz".to_string());
413	
414	    let err =
415	        verify_completion(&fx.work, "main", &run).expect_err("bogus bot_chid should fail check 3");
416	    let msg = err.to_string();
417	    assert!(msg.contains(".claude bookmark"), "msg: {msg}");
418	    assert!(msg.contains("zzzzzzzzzzzz"), "msg: {msg}");
419	}
420	
421	/// The property that replaced resume: rerunning a completed push
422	/// is safe and changes nothing. Every stage no-ops — commit-work
423	/// skips an empty `@`, `message` doesn't demand a title when
424	/// neither side will commit, bookmark-set is a set, and jj's push
425	/// reports nothing to do.
426	#[test]
427	fn push_rerun_after_completion_is_a_noop() {
428	    let fx = Fixture::new("push-rerun");
